@app.get("/api/v1/internal/stream-posts/pending", tags=["Internal"])
async def internal_stream_posts_pending(
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Living stream posts whose rendered state lags the desired state
    (migration 226). Revision-acked (#175); the Discord message id is stored
    server-side so a bot restart cannot orphan the living message (#129).

    Delivery drives the janitor: stale un-finalized sessions (no stream_live
    poll for STREAM_POST_STALE_SECONDS) are finalized HERE, so the "stream
    ended" edit needs no extra loop."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    # Finalize content is composed per row (Sid, Aug 18): the ended edit
    # keeps links — the session's own stored VOD urls when the VM bot
    # resolved them while live, channel archive pages otherwise.
    stale_rows = (await db.execute(text("""
        SELECT post_key, twitch_vod_url, youtube_vod_url, matchups
          FROM stream_channel_posts
         WHERE NOT finalized
           AND last_live_at < NOW() - make_interval(secs => :stale)
    """), {"stale": STREAM_POST_STALE_SECONDS})).mappings().all()
    for sr in stale_rows:
        await db.execute(text("""
            UPDATE stream_channel_posts
               SET finalized = TRUE, content = :c,
                   revision = revision + 1, updated_at = NOW()
             WHERE post_key = :k AND NOT finalized
        """), {"k": sr["post_key"],
               "c": _stream_ended_content(sr["twitch_vod_url"], sr["youtube_vod_url"],
                                          sr["matchups"])})
    await db.commit()
    # Un-finalized rows are ALWAYS returned (review F9): a live post with an
    # acked revision still needs its bottom-anchor check every tick — burial
    # is a channel event, not a content revision. The bot skips the no-op
    # case (revision acked AND not buried) without editing.
    rows = (await db.execute(text("""
        SELECT post_key, channel_id, content, revision, finalized,
               message_id, posted_revision, youtube_vod_url
          FROM stream_channel_posts
         WHERE posted_revision IS DISTINCT FROM revision
            OR NOT finalized
         ORDER BY updated_at
         LIMIT 5
    """))).mappings().all()
    # youtube_vod_url rides along for the bot's stream-chat bridge: an
    # un-finalized row IS the "stream live" signal, and its video id is what
    # the YouTube chat reader attaches to (Aug 18).
    return {"posts": [dict(r) for r in rows]}


@app.post("/api/v1/internal/stream-posts/ack", tags=["Internal"])
async def internal_stream_posts_ack(
    post_key: str = Query(..., max_length=64),
    revision: int = Query(..., ge=1),
    message_id: str | None = Query(None, max_length=32),
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bind the ack to the exact revision rendered (#175): a content change
    that lands between the bot's fetch and its ack leaves revision >
    posted_revision, so the row stays pending and the newer content is
    re-delivered next tick."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    await db.execute(text("""
        UPDATE stream_channel_posts
           SET posted_revision = :rev,
               message_id = COALESCE(:mid, message_id)
         WHERE post_key = :k
    """), {"rev": revision, "mid": message_id, "k": post_key})
    await db.commit()
    return {"status": "acked", "post_key": post_key, "revision": revision}


@app.get("/api/v1/internal/tournament-notices", tags=["Internal"])
async def internal_tournament_notices(
    unnotified: bool = Query(True),
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-poll endpoint (v1.32): tournament DM notices (availability checks
    24-96h before a viable tournament's start/lock). Joined to the player +
    tournament so the bot needs zero extra lookups. Durable ack pattern
    (learning #105) — ack via POST /internal/tournament-notices/ack after the
    DM lands (or is permanently undeliverable); transient failures don't ack
    so the next tick retries. Rows are queued by tournament_tick."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    where = "tn.notified_at IS NULL" if unnotified else "TRUE"
    rows = (await db.execute(text(f"""
        SELECT tn.id                  AS notice_id,
               tn.tournament_id::text AS tournament_id,
               tn.notice_type,
               tn.payload,
               tn.created_at,
               p.steam_id,
               p.discord_id,
               p.display_name,
               t.kind,
               t.status,
               t.min_players,
               t.scheduled_start_ts,
               t.default_start_ts,
               t.lock_at
          FROM tournament_notices tn
          JOIN players p ON p.id = tn.player_id
          JOIN tournaments t ON t.id = tn.tournament_id
         WHERE {where}
      ORDER BY tn.created_at ASC
         LIMIT 20"""))).mappings().all()
    return {
        "notices": [
            {
                "notice_id": str(r["notice_id"]),
                "tournament_id": r["tournament_id"],
                "notice_type": r["notice_type"],
                "payload": r["payload"],
                "created_at": r["created_at"].isoformat() if r["created_at"] else None,
                "steam_id": r["steam_id"],
                "discord_id": r["discord_id"],
                "display_name": r["display_name"],
                "kind": r["kind"],
                "status": r["status"],
                "min_players": r["min_players"],
                "scheduled_start_ts": r["scheduled_start_ts"].isoformat() if r["scheduled_start_ts"] else None,
                "default_start_ts": r["default_start_ts"].isoformat() if r["default_start_ts"] else None,
                "lock_at": r["lock_at"].isoformat() if r["lock_at"] else None,
            }
            for r in rows
        ],
    }


class _TournamentNoticeAck(BaseModel):
    notice_ids: list[str]
    # Aug 15 (Codex tournament-batch r1 find 2, learning #175): the match-
    # result kinds RE-ARM a row in place (ON CONFLICT DO UPDATE keeps the
    # UUID, swaps the payload), so an id-only ack can mark a payload the bot
    # never rendered as delivered. revisions maps notice_id -> the payload's
    # match_id the bot actually SENT; those ids ack via a compare-and-set on
    # that value, so a stale or in-flight ack against a re-armed row fails
    # and the new payload is re-fetched next tick. Ids absent from the map
    # keep the legacy id-only ack (availability_check rows never re-arm).
    revisions: dict[str, str] | None = None


@app.post("/api/v1/internal/tournament-notices/ack", tags=["Internal"])
async def ack_tournament_notices(
    body: _TournamentNoticeAck,
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-only (v1.32): mark tournament notices delivered so the unnotified
    poll stops returning them (mirror of the bug-report events ack). Since
    Aug 15, match-result acks are revision-CAS — see _TournamentNoticeAck."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    ids = [i for i in body.notice_ids[:200] if i]
    if not ids:
        return {"acked": 0}
    revs = body.revisions or {}
    plain = [i for i in ids if i not in revs]
    acked = 0
    if plain:
        # Bare-id acks are LEGACY (pre-revision bots) and may only touch
        # availability rows (Codex tournament r2 find 3): during an
        # api-before-bot rollout the old bot ack-skips every kind it doesn't
        # recognize with a bare id — without this type restriction that
        # permanently marked undelivered match-result notices as delivered
        # before the bot that can send them ever started. A refused bare-id
        # ack just means the row returns next poll until the new bot lands.
        res = await db.execute(text(
            "UPDATE tournament_notices SET notified_at = NOW() "
            "WHERE id::text = ANY(:ids) AND notified_at IS NULL "
            "  AND notice_type = 'availability_check'"
        ), {"ids": plain})
        acked += res.rowcount or 0
    for nid in ids:
        if nid not in revs:
            continue
        res = await db.execute(text(
            "UPDATE tournament_notices SET notified_at = NOW() "
            "WHERE id::text = :id AND notified_at IS NULL "
            "  AND COALESCE(payload::jsonb ->> 'match_id', '') = :rev"
        ), {"id": nid, "rev": str(revs[nid] or "")})
        acked += res.rowcount or 0
    await db.commit()
    return {"acked": acked}


@app.get("/api/v1/internal/pending-dms", tags=["Internal"])
async def internal_pending_dms(
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-poll endpoint: generic one-off DM queue (pending_dms, migration
    129). Rows are inserted by migrations/admin SQL; the bot DMs the linked
    player and acks. Durable ack pattern (learning #105): delivered_at NULL
    and not undeliverable = pending; transient send failures don't ack so the
    next tick retries. Serializes the pk as "dm_id" — the bot reads the same
    key (learning #152)."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    rows = (await db.execute(text("""
        SELECT d.id AS dm_id, d.steam_id, d.content, d.created_at,
               p.discord_id, p.display_name
          FROM pending_dms d
          LEFT JOIN players p ON p.steam_id = d.steam_id
         WHERE d.delivered_at IS NULL AND NOT d.undeliverable
      ORDER BY d.created_at ASC
         LIMIT 20"""))).mappings().all()
    return {
        "dms": [
            {
                "dm_id": str(r["dm_id"]),
                "steam_id": r["steam_id"],
                "discord_id": r["discord_id"],
                "display_name": r["display_name"] or "",
                "content": r["content"],
                "created_at": r["created_at"].isoformat() if r["created_at"] else None,
            }
            for r in rows
        ],
    }


class _PendingDmAck(BaseModel):
    dm_ids: list[str]
    undeliverable: bool = False


@app.post("/api/v1/internal/pending-dms/ack", tags=["Internal"])
async def ack_pending_dms(
    body: _PendingDmAck,
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-only: mark pending DMs delivered (or permanently undeliverable —
    unlinked player / DMs closed) so the poll stops returning them."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    ids = [i for i in body.dm_ids[:200] if i]
    if not ids:
        return {"acked": 0}
    res = await db.execute(text(
        "UPDATE pending_dms SET delivered_at = NOW(), undeliverable = :und "
        "WHERE id::text = ANY(:ids) AND delivered_at IS NULL"
    ), {"ids": ids, "und": bool(body.undeliverable)})
    await db.commit()
    return {"acked": res.rowcount or 0}


# ── Routes: LFP Discord ping (July 21) ───────────────────────
# In-game "LFP Ping" button → POST /lfp-ping queues a row in lfp_pings; the
# bot's poll_lfp_pings loop drains it into the queue-beacon channel with a
# role ping (durable ack pattern, learning #105 family). The table doubles as
# the 1-hour cooldown store (MAX(created_at) per steam_id — survives
# restarts, multi-worker-safe, learning #125). ALL gate outcomes are HTTP 200
# with a status field: the client's PostRequest only surfaces request.error
# on non-2xx, so a 429-style design would show "HTTP/1.1 429" with no
# remaining-time info.

LFP_COOLDOWN_SECONDS = 3600
LFP_VALID_EXPIRY_MINUTES = (15, 30, 60, 180)


class LfpPingRequest(BaseModel):
    steam_id: str = Field(..., max_length=20)
    message: str = Field("", max_length=300)
    expires_minutes: int = 60
    # Aug 7 item 11: comma-joined mode picks ("1v1,ffa"); default matches
    # pre-modes clients so old builds keep working unchanged.
    modes: str = Field("1v1", max_length=32)


@app.post("/api/v1/lfp-ping", tags=["Players"])
async def lfp_ping(req: LfpPingRequest, request: Request, db: AsyncSession = Depends(get_db)):
    """Queue a 'Looking For Player' Discord role ping for a linked player."""
    # Session enforcement (mirrors unlock_achievement): the output is a public
    # Discord post under the claimed player's name + mention, so a spoofed
    # steam_id here is an impersonation/harassment surface once armed.
    await _check_steam_session(request, req.steam_id, db)
    exp_min = req.expires_minutes if req.expires_minutes in LFP_VALID_EXPIRY_MINUTES else 60
    player = (await db.execute(
        select(Player).where(Player.steam_id == req.steam_id)
    )).scalar_one_or_none()
    if player is None or player.deleted_at is not None or not player.discord_id:
        return {"status": "not_linked"}
    if not player.ranked_enabled:
        return {"status": "ranked_disabled"}
    elapsed = (await db.execute(text(
        "SELECT EXTRACT(EPOCH FROM (NOW() - MAX(created_at)))::int "
        "  FROM lfp_pings WHERE steam_id = :sid"
    ), {"sid": req.steam_id})).scalar()
    if elapsed is not None and int(elapsed) < LFP_COOLDOWN_SECONDS:
        return {"status": "cooldown", "seconds_left": LFP_COOLDOWN_SECONDS - int(elapsed)}
    # Sanitize the message (defense-in-depth on top of the bot's
    # allowed_mentions, which is the real anti-injection gate): angle brackets
    # → parens kills <@id>/<@&id>/<#ch> syntax (mirrors _sanitize_item_text),
    # @everyone/@here neutered case-insensitively, link-shaped text stripped
    # (the trusted bot account must never relay attacker URLs — the bot also
    # sends suppress_embeds=True as a second layer), newlines collapsed, 200
    # char clamp.
    msg = (req.message or "").replace("<", "(").replace(">", ")")
    msg = _re.sub(r"@everyone", "everyone", msg, flags=_re.IGNORECASE)
    msg = _re.sub(r"@here", "here", msg, flags=_re.IGNORECASE)
    msg = _re.sub(r"(?i)\b(?:https?://|www\.|discord(?:app)?\.(?:gg|com/invite)/)\S+",
                  "(link removed)", msg)
    msg = _re.sub(r"[\r\n]+", " ", msg).strip()[:200]
    # Aug 7 item 11: mode multi-select. Canonicalize against a closed allowlist
    # (split, lowercase, dedupe, FIXED order) — never interpolated into SQL and
    # never echoed raw (#188 mindset). Empty/garbage falls back to 1v1, which
    # is also what pre-modes clients get via the Pydantic default.
    _mode_order = ("1v1", "2v2", "ffa")
    picked = {m.strip().lower() for m in (req.modes or "").split(",")}
    modes = ",".join(m for m in _mode_order if m in picked) or "1v1"
    await db.execute(text(
        "INSERT INTO lfp_pings (steam_id, message, expires_minutes, expires_at, modes) "
        "VALUES (:sid, :msg, :m, NOW() + make_interval(mins => :m), :modes)"
    ), {"sid": req.steam_id, "msg": msg, "m": exp_min, "modes": modes})
    await db.commit()
    return {"status": "queued", "cooldown_seconds": LFP_COOLDOWN_SECONDS}


@app.get("/api/v1/internal/lfp-pings", tags=["Internal"])
async def internal_lfp_pings(
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-poll endpoint: pending LFP role pings. Serializes the pk as
    "ping_id" and precomputes "expires_unix" server-side — the bot reads the
    exact same keys (learning #152). The expires_at > NOW() filter self-heals
    stale rows (they still count for the cooldown, which reads created_at)."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    rows = (await db.execute(text("""
        SELECT l.id AS ping_id, l.steam_id, l.message, l.modes, l.expires_minutes,
               EXTRACT(EPOCH FROM l.expires_at)::bigint AS expires_unix,
               p.discord_id, p.display_name
          FROM lfp_pings l
          LEFT JOIN players p ON p.steam_id = l.steam_id
         WHERE l.posted_at IS NULL AND NOT l.undeliverable AND l.expires_at > NOW()
      ORDER BY l.created_at ASC
         LIMIT 20"""))).mappings().all()
    return {
        "pings": [
            {
                "ping_id": str(r["ping_id"]),
                "steam_id": r["steam_id"],
                "message": r["message"] or "",
                # Aug 7 item 11: bot renders "LFP: 1v1+FFA for 30min" from
                # these two — key names read verbatim bot-side (#152).
                "modes": r["modes"] or "1v1",
                "expires_minutes": int(r["expires_minutes"] or 60),
                "expires_unix": int(r["expires_unix"]) if r["expires_unix"] is not None else 0,
                "discord_id": r["discord_id"],
                "display_name": r["display_name"] or "",
            }
            for r in rows
        ],
    }


class _LfpPingAck(BaseModel):
    ping_ids: list[str]
    undeliverable: bool = False


@app.post("/api/v1/internal/lfp-pings/ack", tags=["Internal"])
async def ack_lfp_pings(
    body: _LfpPingAck,
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Bot-only: mark LFP pings posted (or permanently undeliverable) so the
    pending poll stops returning them (mirror of the pending-dms ack)."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    ids = [i for i in body.ping_ids[:200] if i]
    if not ids:
        return {"acked": 0}
    res = await db.execute(text(
        "UPDATE lfp_pings SET posted_at = NOW(), undeliverable = :und "
        "WHERE id::text = ANY(:ids) AND posted_at IS NULL"
    ), {"ids": ids, "und": bool(body.undeliverable)})
    await db.commit()
    return {"acked": res.rowcount or 0}


# ── Routes: Privacy ──────────────────────────────────────────

@app.delete("/api/v1/players/{steam_id}/data", tags=["Privacy"])
async def delete_player_data(steam_id: str, request: Request, sig: str = Query(...), db: AsyncSession = Depends(get_db)):
    """
    Anonymize a player's identity. Irreversible.

    Match records, card picks, Elo history, and opponent records are kept
    intact — deleting them would rewrite W/L counts and retroactively change
    other players' ratings on the next Glicko recalc. Instead:

      - steam_id → deleted_<short-uuid>
      - display_name → "[Deleted User]"
      - discord_id, discord_username → NULL
      - ranked_enabled → false (drops from matchmaking immediately)
      - deleted_at stamped so the row is hidden from leaderboards
      - personal-only rows (achievements, link codes, 1v1/2v2/1v2 queue
        entries, blocks, Steam sessions) deleted

    Requires an HMAC signature over "delete:{steam_id}" using the mod secret,
    AND a verified Steam session for the same steam_id — STRICT, not the
    armed/soft helper: the HMAC secret ships inside every client DLL, so on
    its own it must not authorize an irreversible action against an arbitrary
    account (security item A3), and the soft carve-outs (old X-Mod-Version
    claims, unarmed accounts) are exactly what an attacker would present
    (Codex review find). Two deliberate exceptions: STEAM_WEB_API_KEY unset
    (no-op pipeline mode — nothing can be verified) and BANNED accounts —
    a ban revokes sessions and blocks re-minting, and the right to delete
    your own data must survive a ban, so a banned account falls back to
    HMAC-only (the pre-batch protection level).
    """
    if not MATCH_HMAC_SECRET:
        raise HTTPException(status_code=503, detail="HMAC not configured")

    expected = hmac.new(
        MATCH_HMAC_SECRET.encode(),
        f"delete:{steam_id}".encode(),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(sig, expected):
        raise HTTPException(status_code=403, detail="Invalid signature")

    # `is None`, not truthiness (round-16 find 5): a legacy reason="" ban is
    # an ACTIVE ban whose sessions are already purged — the truthiness form
    # demanded a session that player structurally cannot mint, stranding
    # their documented HMAC-only deletion path.
    if os.getenv("STEAM_WEB_API_KEY") and (await _is_banned(db, steam_id)) is None:
        token = None
        try:
            if request is not None:
                token = request.headers.get("X-Session-Token")
        except Exception:
            token = None
        session_ok = False
        if token:
            try:
                srow = (await db.execute(text(
                    "SELECT steam_id, verified, expires_at FROM steam_sessions "
                    "WHERE token_hash = :th"
                ), {"th": hashlib.sha256(token.encode()).hexdigest()})).mappings().first()
                session_ok = (
                    srow is not None
                    and bool(srow["verified"])
                    and srow["steam_id"] == steam_id
                    and (srow["expires_at"] is None
                         or srow["expires_at"] >= datetime.now(timezone.utc))
                )
            except Exception as ex:
                # Infra failure: fail CLOSED here (unlike the soft helper) —
                # a retryable 503 on an irreversible action beats a bypass.
                print(f"[PRIVACY] delete session lookup error: {type(ex).__name__}")
                raise HTTPException(status_code=503, detail="session_check_unavailable")
        if not session_ok:
            raise HTTPException(
                status_code=401,
                detail="session_required_update_mod",
            )

    # Identity lock FIRST (round-14 find 1): before the authoritative player
    # read and before ANY queue/lobby/lease discovery or sweep. An enrollment
    # writer holding this lock commits its row before our sweeps run; one
    # that hasn't acquired it yet blocks, then fails its post-lock tombstone/
    # live re-reads. Global order: identity -> lobby/series -> queue -> lease.
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"), {"sid": steam_id})
    player = (await db.execute(select(Player).where(Player.steam_id == steam_id))).scalar_one_or_none()
    if player is None:
        return {"status": "not_found", "steam_id": steam_id}
    if player.deleted_at is not None:
        return {"status": "already_deleted", "steam_id": steam_id}

    pid = player.id

    # Drop purely personal rows — no cross-player impact.
    await db.execute(text("DELETE FROM player_achievements WHERE player_id = :pid"), {"pid": pid})
    await db.execute(text("DELETE FROM link_codes WHERE player_id = :pid"), {"pid": pid})
    # This endpoint must not wait on a live decline/poll and must not discover a
    # pair, then broad-DELETE a newly re-paired row that was outside that stale
    # discovery set (#148/#150). Delete only rows the subqueries actually locked.
    # If anything remains, roll the whole anonymization transaction back and ask
    # the caller to retry; partial personal-data cleanup is not acceptable.
    await db.execute(text("""
        DELETE FROM queue_blocks
        WHERE ctid IN (
            SELECT ctid FROM queue_blocks
            WHERE blocker_id = :pid OR blocked_id = :pid
            FOR UPDATE SKIP LOCKED
        )
    """), {"pid": pid})
    blocks_left = (await db.execute(text(
        "SELECT 1 FROM queue_blocks "
        "WHERE blocker_id = :pid OR blocked_id = :pid LIMIT 1"
    ), {"pid": pid})).first()
    if blocks_left is not None:
        await db.rollback()
        raise HTTPException(status_code=503, detail="account_cleanup_contended")

    await db.execute(text("""
        DELETE FROM ranked_queue
        WHERE player_id IN (
            SELECT player_id FROM ranked_queue
            WHERE player_id = :pid OR matched_with = :pid
            FOR UPDATE SKIP LOCKED
        )
    """), {"pid": pid})
    queue_left = (await db.execute(text(
        "SELECT 1 FROM ranked_queue "
        "WHERE player_id = :pid OR matched_with = :pid LIMIT 1"
    ), {"pid": pid})).first()
    if queue_left is not None:
        await db.rollback()
        raise HTTPException(status_code=503, detail="account_cleanup_contended")

    # 2v2 and 1v2 queue rows carry COPIED raw steam_id + display_name, and the
    # player row is anonymized rather than deleted, so ON DELETE CASCADE never
    # fires for them — they must be cleared explicitly or the identity survives
    # the anonymization (privacy audit HIGH). Same SKIP LOCKED + verify shape as
    # ranked_queue above. Codex review find: also DISSOLVE any zero-progress
    # locked group the deleted account was part of (mirror of the leave
    # endpoints) — otherwise the other members can reset themselves one by one
    # and leave a forever-'active' series shell no janitor predicate can find.
    _grp = (await db.execute(text(
        "SELECT series_id FROM team_queue WHERE player_id = :pid AND series_id IS NOT NULL"
    ), {"pid": pid})).scalars().all()
    _ovt_grp = (await db.execute(text(
        "SELECT series_id FROM ovt_queue WHERE player_id = :pid AND series_id IS NOT NULL"
    ), {"pid": pid})).scalars().all()
    _ffa_grp = (await db.execute(text(
        "SELECT series_id FROM ffa_queue WHERE player_id = :pid AND series_id IS NOT NULL"
    ), {"pid": pid})).scalars().all()
    # Aug 6 item 9: a 'lobby' row's series_id points at team_lobbies /
    # ovt_lobbies, NOT at the mode's series table. It is therefore already
    # inside _grp/_ovt_grp above (which filter only on "series_id IS NOT
    # NULL"), where the series locks and series UPDATEs simply no-op against a
    # lobby id. Collect the LOBBY ids separately so the open-lobby
    # remove/promote/disband step below can run for them, exactly as FFA's
    # does. UUIDs cannot collide across the two tables, so a lobby id in _grp
    # is harmless — it just matches nothing.
    _team_lob = (await db.execute(text(
        "SELECT series_id FROM team_queue WHERE player_id = :pid"
        " AND status = 'lobby' AND series_id IS NOT NULL"
    ), {"pid": pid})).scalars().all()
    _ovt_lob = (await db.execute(text(
        "SELECT series_id FROM ovt_queue WHERE player_id = :pid"
        " AND status = 'lobby' AND series_id IS NOT NULL"
    ), {"pid": pid})).scalars().all()
    # Review find 8: FFA's canonical writer order is LOBBY row first, then its
    # queue members (leave/poll/janitor all take it that way). Deleting the
    # queue row first and touching ffa_lobbies afterwards inverts that and
    # deadlocks against a concurrent leave/poll. Take the lobby locks here,
    # BEFORE the queue-row deletes below, in canonical UUID order.
    for _lid in sorted(_ffa_grp, key=str):
        await db.execute(text(
            "SELECT 1 FROM ffa_lobbies WHERE id = :lid FOR NO KEY UPDATE"
        ), {"lid": _lid})
    # Round-15 find 2: the SAME series-first order for team and OVT — the
    # completion paths lock series (FOR UPDATE) then members
    # (_lock_queue_rows_ordered), so deleting queue rows first and updating
    # the series after was a textbook ABBA. FOR NO KEY UPDATE per #202: the
    # weakest mode that conflicts with our own series UPDATEs below and with
    # completion's FOR UPDATE, without enrolling FK KEY SHARE inserts.
    for _sid in sorted(_grp, key=str):
        await db.execute(text(
            "SELECT 1 FROM team_series WHERE id = :sid FOR NO KEY UPDATE"
        ), {"sid": _sid})
    for _sid in sorted(_ovt_grp, key=str):
        await db.execute(text(
            "SELECT 1 FROM ovt_series WHERE id = :sid FOR NO KEY UPDATE"
        ), {"sid": _sid})
    # Aug 6 item 9: same parent-before-members order for the new lobby tables
    # (round-15 find 2 / #202 — FOR NO KEY UPDATE is the weakest mode that
    # still conflicts with our own UPDATEs below without enrolling every FK
    # KEY SHARE insert in our lock graph).
    for _lid in sorted(_team_lob, key=str):
        await db.execute(text(
            "SELECT 1 FROM team_lobbies WHERE id = :lid FOR NO KEY UPDATE"
        ), {"lid": _lid})
    for _lid in sorted(_ovt_lob, key=str):
        await db.execute(text(
            "SELECT 1 FROM ovt_lobbies WHERE id = :lid FOR NO KEY UPDATE"
        ), {"lid": _lid})
    _discovered = {"team_queue": {str(s) for s in _grp},
                   "ovt_queue": {str(s) for s in _ovt_grp},
                   "ffa_queue": {str(s) for s in _ffa_grp}}
    for _qt in ("team_queue", "ovt_queue", "ffa_queue"):
        _gone = (await db.execute(text(f"""
            DELETE FROM {_qt}
            WHERE player_id IN (
                SELECT player_id FROM {_qt}
                WHERE player_id = :pid
                FOR UPDATE SKIP LOCKED
            )
            RETURNING series_id
        """), {"pid": pid})).scalars().all()
        # Round-16 find 4: a matcher that does NOT take our identity lock can
        # form a group with this player between our parent DISCOVERY above
        # and this DELETE — the delete then removes a freshly-grouped row
        # whose parent our in-memory lists never saw, leaving an active
        # series/lobby anchored to the deleted member. The DELETE's own
        # RETURNING is the authoritative membership read (#208): any parent
        # it reveals that discovery missed means the snapshot went stale —
        # roll everything back and let the caller retry against the new
        # truth. (Locking the new parent HERE would invert queue->parent.)
        if any(s is not None and str(s) not in _discovered[_qt] for s in _gone):
            await db.rollback()
            raise HTTPException(status_code=503, detail="account_cleanup_contended")
        _qleft = (await db.execute(text(
            f"SELECT 1 FROM {_qt} WHERE player_id = :pid LIMIT 1"
        ), {"pid": pid})).first()
        if _qleft is not None:
            await db.rollback()
            raise HTTPException(status_code=503, detail="account_cleanup_contended")
    for _sid in _grp:
        await db.execute(text(
            """UPDATE team_series SET status='cancelled', invalidated_at=NOW(),
                      invalidation_reason='member_deleted'
                WHERE id=:sid AND status='active' AND spawn_confirmations < 4"""),
            {"sid": _sid})
        await _reconcile_team_series_bets(db, _sid, "member deleted")
        # Codex r2 f2: hosted-aware disposition, same guard as before — only
        # when the cancel above actually landed (a live game keeps its group).
        if (await db.execute(text(
            "SELECT 1 FROM team_series WHERE id=:sid"
            "   AND invalidation_reason='member_deleted'"), {"sid": _sid})).scalar():
            await _dissolve_group_rows(db, "team", _sid)
    for _sid in _ovt_grp:
        await db.execute(text(
            """UPDATE ovt_series SET status='canceled', invalidation_reason='member_deleted',
                      invalidated_at=NOW()
                WHERE id=:sid AND status='active'
                  AND NOT EXISTS (SELECT 1 FROM ovt_matches m WHERE m.series_id=:sid)"""),
            {"sid": _sid})
        # Codex r2 f2: hosted-aware disposition, same landed-cancel guard.
        if (await db.execute(text(
            "SELECT 1 FROM ovt_series WHERE id=:sid"
            "   AND invalidation_reason='member_deleted'"), {"sid": _sid})).scalar():
            await _dissolve_group_rows(db, "ovt", _sid)
    # Aug 6 item 9: promote or disband the 2v2 / 1v2 open lobbies the deleted
    # account was sitting in. Without this the lobby keeps pointing at the
    # anonymized account as host and nothing else ever repairs it (the series
    # UPDATEs above cannot — a lobby id matches no series row).
    for _lmode, _qt, _lt, _lids in (("team", "team_queue", "team_lobbies", _team_lob),
                                    ("ovt", "ovt_queue", "ovt_lobbies", _ovt_lob)):
        for _lid in _lids:
            _ol = (await db.execute(text(
                f"SELECT id, host_player_id FROM {_lt} WHERE id=:lid AND status='open'"
                " FOR UPDATE SKIP LOCKED"), {"lid": _lid})).mappings().first()
            if _ol is None:
                continue
            _live = (await db.execute(text(f"""
                SELECT player_id FROM {_qt}
                 WHERE series_id = :lid AND status = 'lobby' AND player_id <> :pid
                 ORDER BY joined_at, player_id::text"""),
                {"lid": _lid, "pid": pid})).scalars().all()
            if not _live:
                _killed = (await db.execute(text(
                    f"""UPDATE {_lt} SET status='canceled', invalidated_at=NOW(),
                              invalidation_reason='lobby_disbanded'
                        WHERE id=:lid AND status='open'
                       RETURNING id"""), {"lid": _lid})).scalar()
                # Terminal transition landed -> the lobby will never start, so
                # its held lobby-phase wagers come back (migration 207).
                # No-op for 'ovt'. A promotion (the elif) dissolves nothing.
                if _killed is not None:
                    await _refund_lobby_bets(db, _lmode, _lid, "lobby_disbanded")
            elif _ol["host_player_id"] == pid:
                await db.execute(text(
                    f"UPDATE {_lt} SET host_player_id=:h WHERE id=:lid"
                ), {"h": _live[0], "lid": _lid})

    for _lid in _ffa_grp:
        # OPEN host lobby (July 29 redesign): run the same remove/promote/
        # disband step an explicit Leave performs — without it the open lobby
        # would keep pointing at the anonymized account as host (design
        # review find 7). SKIP LOCKED because deletion already holds the
        # player's queue rows (the pre-existing row->series order): if a
        # concurrent Start/Join holds the lobby, do nothing — the generic row
        # DELETE below still removes the membership and the janitor promotes
        # or disbands within a minute.
        _ol = (await db.execute(text(
            "SELECT id, host_player_id FROM ffa_lobbies WHERE id=:lid AND status='open'"
            " FOR UPDATE SKIP LOCKED"), {"lid": _lid})).mappings().first()
        if _ol is not None:
            _live = (await db.execute(text("""
                SELECT player_id FROM ffa_queue
                 WHERE series_id = :lid AND status = 'lobby' AND player_id <> :pid
                 ORDER BY joined_at, player_id::text"""),
                {"lid": _lid, "pid": pid})).scalars().all()
            if not _live:
                _killed = (await db.execute(text(
                    """UPDATE ffa_lobbies SET status='canceled', invalidated_at=NOW(),
                              invalidation_reason='lobby_disbanded'
                        WHERE id=:lid AND status='open'
                       RETURNING id"""), {"lid": _lid})).scalar()
                # Terminal transition landed -> refund the held lobby-phase
                # wagers (migration 207). A promotion dissolves nothing.
                if _killed is not None:
                    await _refund_lobby_bets(db, "ffa", _lid, "lobby_disbanded")
            elif _ol["host_player_id"] == pid:
                await db.execute(text(
                    "UPDATE ffa_lobbies SET host_player_id=:h WHERE id=:lid"
                ), {"h": _live[0], "lid": _lid})
        await db.execute(text(
            """UPDATE ffa_lobbies SET status='canceled', invalidation_reason='member_deleted',
                      invalidated_at=NOW()
                WHERE id=:lid AND status='active' AND games_played = 0"""),
            {"lid": _lid})
        # Round-2 review find 7: a PLAYED lobby whose member deleted their
        # account must also close (their anonymized Steam ID can never pass
        # the roster check again, so no future report can land) — completed,
        # not canceled: real games happened.
        await db.execute(text(
            """UPDATE ffa_lobbies SET status='completed', completed_at=NOW()
                WHERE id=:lid AND status='active' AND games_played > 0"""),
            {"lid": _lid})
        # Reconcile, not blanket-refund: a PLAYED lobby can hold bets whose
        # game has a recorded winner (#241 — those settle, the rest refund).
        await _reconcile_ffa_lobby_bets(db, _lid, "member deleted")
        await db.execute(text(
            """UPDATE ffa_queue SET status='searching', series_id=NULL, slot=NULL,
                      room_name=NULL, room_region=NULL, matched_at=NULL, joined_at=NOW()
                WHERE series_id=:lid
                  AND EXISTS (SELECT 1 FROM ffa_lobbies l WHERE l.id=:lid
                              AND l.status NOT IN ('active', 'open'))"""),
            {"lid": _lid})

    # Steam sessions store the raw Steam ID (and authenticate as it) — purge
    # them so no live token outlives the account.
    # Queue lease LAST, after every series/lobby lock pass above.
    #
    # Position is load-bearing, not stylistic. Match formation locks in the
    # order lobby/series -> queue rows -> lease. Deleting the lease up front
    # (where this first went) would hold the lease tuple while this function
    # then waits for ffa_lobbies FOR NO KEY UPDATE — the exact inverse — so a
    # concurrent FFA Start holding the lobby and waiting on the lease closes an
    # ABBA cycle and one of the two transactions dies. Taking it here means the
    # lease is the last thing acquired, matching everyone else.
    #
    # Needed at all because this endpoint ANONYMISES the players row rather
    # than deleting it, so queue_leases' ON DELETE CASCADE never fires.
    await db.execute(text("DELETE FROM queue_leases WHERE player_id = :pid"),
                     {"pid": pid})
    # Identity lock BEFORE the session purge (round-13 find 2): a steam_auth
    # finalization holding the lock could otherwise insert a fresh raw-id
    # session between our purge and our commit. Locking first forces its
    # post-await tombstone re-read to wait behind this whole transaction.
    # (Round-11 find 1: the same lock serializes in-flight portal mutations —
    # they commit before this sweep and are swept, or block and then fail
    # their post-lock rechecks.)
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"), {"sid": steam_id})
    await db.execute(text("DELETE FROM steam_sessions WHERE steam_id = :sid"), {"sid": steam_id})
    await db.execute(text("DELETE FROM player_blocks WHERE blocker_id = :pid OR blocked_id = :pid"), {"pid": pid})

    # i18n surfaces (Codex wave-2 round-10 find 2): the portal token and
    # translate grants are LIVE AUTHORITY and must die with the account, and
    # every identity-bearing i18n column falls under the same anonymization
    # contract as the player row. Tombstone computed first so the rewrites
    # share it.
    short = uuid.uuid4().hex[:8]
    _tomb = f"deleted_{short}"
    # Captured up front: the player row is anonymized further down and clears
    # discord_id, but the Discord-authored chat/audit scrub below needs it.
    _prior_discord_id = getattr(player, "discord_id", None)
    await db.execute(text("DELETE FROM i18n_portal_sessions WHERE steam_id = :sid"), {"sid": steam_id})
    await db.execute(text(
        "UPDATE language_grants SET revoked_at = COALESCE(revoked_at, NOW()),"
        "       steam_id = :tomb WHERE steam_id = :sid"), {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE language_grants SET granted_by_steam_id = :tomb WHERE granted_by_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE i18n_proposals SET proposer_steam_id = :tomb WHERE proposer_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE i18n_proposals SET reviewed_by_steam_id = :tomb WHERE reviewed_by_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE i18n_entries SET approved_by_steam_id = :tomb WHERE approved_by_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    # Round-11 find 5: the actor rewrite and the detail scrub are SEPARATE
    # populations — a single combined UPDATE stamped the tombstone onto an
    # UNRELATED admin's actor_steam_id whenever the deleted id merely
    # appeared in that row's detail text.
    await db.execute(text(
        "UPDATE i18n_review_events SET actor_steam_id = :tomb"
        " WHERE actor_steam_id = :sid"), {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE i18n_review_events SET detail = REPLACE(detail, :sid, :tomb)"
        " WHERE detail LIKE '%' || :sid || '%'"), {"sid": steam_id, "tomb": _tomb})

    # Aug 6 item 5 tables (Codex round 1, MEDIUM): chat moderation is new and
    # stores RAW steam ids in three places, all of which survived deletion —
    # a permanently muted player who deleted their account kept appearing, by
    # steam id, in the moderator mute list forever.
    #
    # The mute itself is REVOKED, not just tombstoned: the account is gone, so
    # there is nothing left to mute, and leaving a live row keyed to a
    # tombstone would silently gag whoever might later be issued that id.
    await db.execute(text(
        "UPDATE chat_mutes SET revoked_at = COALESCE(revoked_at, NOW()),"
        "       steam_id = :tomb WHERE steam_id = :sid"), {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE chat_mutes SET muted_by_steam_id = :tomb WHERE muted_by_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE chat_messages SET deleted_by_steam_id = :tomb WHERE deleted_by_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    # Codex round 2 (HIGH): the AUTHORED chat rows carry the deleted account's
    # identity too — steam_id, discord_id and the display name embedded in the
    # row — and /chat/recent is an UNAUTHENTICATED read. Tombstoning only the
    # moderator columns left a deleted player's Steam ID and Discord ID being
    # served publicly forever. Anonymize the authored rows on the same contract
    # as the player row itself; the message TEXT is left intact because it is
    # conversation other people took part in, and the row no longer identifies
    # who wrote it.
    await db.execute(text(
        "UPDATE chat_messages SET steam_id = :tomb, discord_id = NULL,"
        "       display_name = '[Deleted User]'"
        " WHERE steam_id = :sid"), {"sid": steam_id, "tomb": _tomb})
    # Codex round 3 (HIGH): a message the player sent THROUGH DISCORD has
    # steam_id NULL and only discord_id set — the relay resolves the linked
    # Steam account to render rank/title but never persists it. Scrubbing by
    # steam_id alone therefore left every Discord-authored line, with its
    # Discord ID and display name, being served by the UNAUTHENTICATED
    # /chat/recent forever. Captured BEFORE the player row is anonymized
    # below, because that clears discord_id.
    if _prior_discord_id:
        await db.execute(text(
            "UPDATE chat_messages SET discord_id = NULL, steam_id = :tomb,"
            "       display_name = '[Deleted User]'"
            " WHERE discord_id = :did"), {"did": _prior_discord_id, "tomb": _tomb})
        # NOTE (round 4): a REPLACE over the serialized JSONB used to run here
        # and has been REMOVED — see the admin_actions note below.
    # admin_actions.details is JSONB and can carry copies of the same ids.
    #
    # REMOVED (Codex round 4, MEDIUM — this was MY regression, not a
    # pre-existing gap): the scrub was a REPLACE over the serialized text,
    # which matches ARBITRARY SUBSTRINGS. Deleting Discord id
    # 407123456789012345 rewrote an unrelated mute reason containing
    # 1407123456789012345 into "1deleted_<suffix>" — corrupting another
    # player's audit row to anonymize this one. A substring rewrite over
    # free-text JSON cannot be made safe by tightening the LIKE; it needs
    # exact per-key path updates against a known details schema, and
    # admin_actions.details has no fixed shape (every action writes its own
    # keys).
    #
    # The identity-bearing COLUMNS (admin_steam_id, target_steam_id) are
    # tombstoned above, which is the part this batch is responsible for. The
    # embedded copies inside details — along with the pre-existing copies in
    # bug_reports, artist_users, release_posts and booster_grants that round 4
    # also enumerated — are a REAL but SEPARATE problem: they predate this
    # work, and patching them table-by-table produced three new findings per
    # round. They need one mechanical inventory of every identity-bearing
    # column and a scrub built from it. Tracked as its own item; deliberately
    # NOT attempted here, because a half-done scrub that corrupts unrelated
    # rows is worse than a known, recorded gap (#242).
    # admin_actions is the moderation audit trail and its FK to admin_users was
    # deliberately dropped (migration 192) so scoped moderators can be logged.
    # Tombstone the actor and target ids the same way the i18n audit is handled.
    await db.execute(text(
        "UPDATE admin_actions SET admin_steam_id = :tomb WHERE admin_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})
    await db.execute(text(
        "UPDATE admin_actions SET target_steam_id = :tomb WHERE target_steam_id = :sid"),
        {"sid": steam_id, "tomb": _tomb})

    # Anonymize the player row. Keep rating_history / glicko / matches untouched
    # so Glicko recalcs and opponent histories stay consistent.
    player.steam_id = f"deleted_{short}"
    player.display_name = "[Deleted User]"
    player.discord_id = None
    player.discord_username = None
    player.ranked_enabled = False
    player.deleted_at = datetime.now(timezone.utc)

    # Record hash so a later match report from the same Steam ID can't
    # spoof a fresh account.
    if MATCH_HMAC_SECRET:
        await db.execute(
            text("INSERT INTO deleted_steam_ids (steam_id_hash) VALUES (:h) ON CONFLICT DO NOTHING"),
            {"h": _hash_steam_id(steam_id)},
        )

    await db.commit()
    print(f"[PRIVACY] Anonymized steam_id={steam_id} (placeholder={player.steam_id})")

    return {"status": "anonymized", "steam_id": steam_id, "placeholder": player.steam_id}


