class _LobbyStartReq(BaseModel):
    steam_id: str


@app.post("/api/v1/team/lobby/start", tags=["Team Queue"])
async def team_lobby_start(req: _LobbyStartReq, request: Request,
                           db: AsyncSession = Depends(get_db)):
    """Host presses Start on a 2v2 lobby: freeze the roster, create the
    team_series row, and put all four queue rows into 'matched' — EXACTLY the
    state the auto-queue's lock produces, so the whole ready-up / room-issuance
    / report pipeline downstream is the existing shipped machinery."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    me, lrow, live = await _lobby_start_common(db, "team", req.steam_id)
    lobby_id = me["series_id"]
    # Team assignment: honor preferred_team exactly as the MANUAL auto-queue
    # does (joining a host lobby IS the consent, so this is the manual path,
    # never the Elo balancer). Members with no preference fill the gaps.
    team1_ids, team2_ids, unassigned = [], [], []
    for m in live:
        pt = m["preferred_team"]
        if pt == 1 and len(team1_ids) < 2:
            team1_ids.append(m["player_id"])
        elif pt == 2 and len(team2_ids) < 2:
            team2_ids.append(m["player_id"])
        else:
            unassigned.append(m["player_id"])
    for pid in unassigned:
        if len(team1_ids) < 2:
            team1_ids.append(pid)
        elif len(team2_ids) < 2:
            team2_ids.append(pid)
    # Canonical t-a / t-b slot order by steam_id WITHIN each team. Load-bearing:
    # the client rebuilds the same order with no extra metadata, so its
    # 11-field HMAC byte-matches what /team/matches recomputes. Without this
    # the arbitrary partition order breaks signature verification.
    pid_to_steam = {m["player_id"]: m["steam_id"] for m in live}
    team1_ids = sorted(team1_ids, key=lambda pid: pid_to_steam[pid])
    team2_ids = sorted(team2_ids, key=lambda pid: pid_to_steam[pid])
    await _assert_no_service_subject(
        db, affected_player_ids=team1_ids + team2_ids)
    # r2 HIGH 2: hosted Start is a same-four CREATION funnel and joins the
    # quartet protocol — without this, four players re-forming their DC'd
    # sitting through a hosted lobby minted a second live series while the
    # played original stayed live. Under the lock, resolve the family: adopt
    # the authoritative resumable row when its stored partition equals the
    # lobby's frozen split (side-swap tolerated — the pick helper's req gate
    # enforces exactly that); a locked family row means "try again in a
    # moment"; otherwise insert fresh (played-but-ineligible rows are left
    # for the janitor/listing arms).
    await _team_quartet_lock(db, team1_ids + team2_ids)
    _pick_outcome, _adopt = await _team_lock_family_pick(
        db, team1_ids + team2_ids, list(team1_ids), list(team2_ids),
        req.steam_id)
    if _pick_outcome == "defer":
        raise HTTPException(409, "A previous series for these four players is "
                                 "being updated - press Start again in a moment")
    if _pick_outcome == "picked":
        # ADOPT: the sitting continues with its score. Use the STORED slot
        # orientation (the lobby split may be the side-swap of it) so
        # team_assigned / HMAC slot canonicalization match the series row.
        series_id = _adopt["id"]
        team1_ids = [_adopt["t1a_id"], _adopt["t1b_id"]]
        team2_ids = [_adopt["t2a_id"], _adopt["t2b_id"]]
        await db.execute(text("""
            UPDATE team_series
               SET status = 'active',
                   dc_grace_until = NULL,
                   dc_team_remaining = NULL,
                   dc_player_id = NULL,
                   photon_room_id = NULL,
                   room_issued_at = NULL,
                   spawn_confirmations = 0,
                   spawn_confirmed_by = '[]'::jsonb,
                   invalidation_reason = CASE
                       WHEN invalidation_reason = 'dc_manual_pending' THEN NULL
                       ELSE invalidation_reason END
             WHERE id = :sid
               AND status IN ('active', 'dc_paused', 'dc_incomplete')
        """), {"sid": series_id})
        # relocked_at is stamped just before the COMMIT below (r4 finding:
        # stamping here left every later lock wait — the wager query, lobby
        # activation, lease acquisition — aging the stamp before it was
        # externally visible, so a long wait could expire the 10-minute DC
        # fence pre-commit; the queue/sticky helper already stamps last).
        # Colour identity stays frozen from the series' own creation — no
        # re-stamp (it would re-decide a decided identity).
        print(f"[2v2-LOBBY] host {req.steam_id} ADOPTED resumable series "
              f"{series_id} (score {_adopt['t1_series_wins']}-{_adopt['t2_series_wins']})")
    else:
        # NOTE: module-level `uuid`, never `uuid_mod` — that alias exists only
        # as a function-local import inside the queue endpoints, and
        # referencing it from a different function is a NameError at runtime
        # (learning #135, bug #70).
        series_id = uuid.uuid4()
        await db.execute(text("""
            INSERT INTO team_series (id, t1a_id, t1b_id, t2a_id, t2b_id,
                                     status, was_auto_balanced, created_at)
            VALUES (:sid, :t1a, :t1b, :t2a, :t2b, 'active', false, NOW())
        """), {"sid": series_id,
               "t1a": team1_ids[0], "t1b": team1_ids[1],
               "t2a": team2_ids[0], "t2b": team2_ids[1]})
        # Aug 8 (Sid): body-colour team identity, decided once, persisted here.
        await _stamp_team_series_colors(db, series_id, team1_ids, team2_ids)
    all4 = team1_ids + team2_ids
    await db.execute(text("""
        UPDATE team_queue
           SET status='matched', series_id=:sid,
               team_assigned = CASE WHEN player_id = ANY(:t1) THEN 1 ELSE 2 END,
               matched_at = NOW(), ready = false,
               room_name = NULL, room_region = NULL
         WHERE player_id = ANY(:all4)
    """), {"sid": series_id, "t1": team1_ids, "all4": all4})
    regions = [m["region"] for m in live if m["region"]]
    region = max(set(regions), key=regions.count) if regions else None
    await _lobby_activate(db, "team", lobby_id, series_id, all4, region, None)
    # Lobby-phase wagers resolve against the roster we just froze (migration
    # 207). Never raises — a bet problem must not fail a Start — and only
    # MARKS refunds; the gold moves after this transaction commits.
    await _bind_lobby_bets(db, "team", lobby_id, {
        "series_id": series_id,
        "teams": {1: list(team1_ids), 2: list(team2_ids)},
        "steam_by_pid": dict(pid_to_steam),
    # r3 HIGH 2: an ADOPTED series already has a decided game — binding
    # lobby wagers into it is a post-result betting window. Refund them all.
    }, refund_all_reason=("adopted_progressed_series"
                          if _pick_outcome == "picked" else None))
    # Assembly-length lease, then renewed by the authenticated in_match ping
    # for as long as battles actually run.
    await _lease_acquire_many(db, all4, "team", series_id, LEASE_TTL_ASSEMBLY)
    if _pick_outcome == "picked":
        # r4 finding (H1 placement): the relock stamp must be the LAST write
        # before commit so the 10-minute DC fence measures externally-visible
        # time — every lock wait this transaction already served is behind
        # us. Savepointed (#235) for pre-migration-235.
        try:
            async with db.begin_nested():
                await db.execute(text(
                    "UPDATE team_series SET relocked_at = clock_timestamp() WHERE id = :sid"
                ), {"sid": series_id})
        except Exception:
            pass
    await db.commit()
    print(f"[2v2-LOBBY] host {req.steam_id} started lobby {lobby_id} "
          f"series {series_id} t1={team1_ids} t2={team2_ids}")
    try:
        await _flush_lobby_bet_refunds(db, "team", lobby_id)
    except Exception as _lbex:
        # Own failure domain (#187): the janitor's 60s retry owns any refund
        # that does not land here.
        print(f"[LOBBY-BETS] post-start refund flush failed for team lobby "
              f"{lobby_id}: {_lbex}")
    await _evict_other_queue_searching(db, all4, "team_queue", "a 2v2 lobby")
    return {"status": "ok", "series_id": str(series_id), "lobby_id": str(lobby_id)}


