def _spectate_roster_list(roster: str) -> list:
    return [s for s in (roster or "").split(",") if s]


async def _spectate_mandatory_class(db: AsyncSession, game) -> str:
    """Classify only an exact, live sync-tournament room binding as mandatory."""
    # DEPLOY GATE: Sid sign-off required (async tournament narrowing)
    # Pair-derived async inference is intentionally absent.  A pair sharing an
    # arbitrary room is ordinary opt-in even when the pair has an async match.
    mode = game.get("mode") if hasattr(game, "get") else game["mode"]
    room = game.get("room_name") if hasattr(game, "get") else game["room_name"]
    source_ref = game.get("source_ref") if hasattr(game, "get") else game["source_ref"]
    if mode != "1v1" or not str(room or "").startswith("sct-") or not source_ref:
        return ""
    try:
        async with db.begin_nested():
            bound = (await db.execute(text("""
                SELECT 1
                  FROM tournament_matches tm
                  JOIN tournaments t ON t.id = tm.tournament_id
                 WHERE tm.id::text = :ref
                   AND tm.photon_room_name = :room
                   AND tm.status IN ('ready', 'scheduled')
                   AND t.status = 'running' AND t.kind = 'sync'
                 LIMIT 1
            """), {"ref": str(source_ref), "room": room})).first()
        return "sync_room" if bound else ""
    except Exception as ex:
        print(f"[SPECTATE] mandatory classifier failed closed: {type(ex).__name__}: {ex}")
        return ""


async def _spectate_game_ready(db: AsyncSession, game) -> tuple[bool, str]:
    """Completeness check (design §6.3): every roster member holds a FRESH
    attestation byte-matching the game row's tuple, and every member still
    allows spectating. Returns (ready, disabled_reason)."""
    roster = _spectate_roster_list(game["roster"])
    if len(roster) != game["fighter_target"]:
        return False, "room_not_ready"
    if game["room_capacity"] < game["fighter_target"] + 1:
        # No reserved seat exists (old-client room creator) — never grant.
        return False, "room_not_ready"
    # A room that has not reported LIVE COMBAT recently is listable but never
    # grantable (Codex r1 find 15): pre-assembly, stuck-assembly and post-
    # game-over rooms all fail here.
    lba = game.get("last_battle_at") if hasattr(game, "get") else game["last_battle_at"]
    if lba is None or lba < datetime.now(timezone.utc) - timedelta(seconds=SPECTATE_ATTEST_FRESH_SECONDS):
        return False, "room_not_ready"
    rows = (await db.execute(text("""
        SELECT steam_id, roster, region, fighter_target, room_capacity, protocol
          FROM spectate_attestations
         WHERE game_id = :gid
           AND attested_at > NOW() - make_interval(secs => :fresh)
    """), {"gid": str(game["id"]), "fresh": SPECTATE_ATTEST_FRESH_SECONDS})).mappings().all()
    by_sid = {r["steam_id"]: r for r in rows}
    for sid in roster:
        r = by_sid.get(sid)
        if r is None:
            return False, "room_not_ready"
        if (r["roster"] != game["roster"]
                or r["region"] != game["room_region"]
                or r["fighter_target"] != game["fighter_target"]
                or r["room_capacity"] != game["room_capacity"]
                # Floor is max(stored, constant) — the running API is
                # authoritative even for rows minted by an older API in a
                # mixed-deploy window (Aug 10 r3 blocker 1).
                or r["protocol"] < max(game["protocol_min"] or 1, SPECTATE_PROTOCOL)):
            return False, "room_not_ready"
    opt = (await db.execute(text("""
        SELECT COUNT(*) AS n FROM players
         WHERE steam_id = ANY(:sids) AND allow_spectators IS NOT TRUE
    """), {"sids": roster})).scalar() or 0
    if opt > 0:
        # DEPLOY GATE: Sid sign-off required (async tournament narrowing)
        # The exact sct- binding is the sole opt-out bypass. Async pairs and
        # sync side games remain ordinary opt-in on every consumer.
        if not await _spectate_mandatory_class(db, game):
            # Generic reason — never reveal WHICH participant opted out (§6.4).
            return False, "spectating_disabled"
    return True, ""


async def _spectate_active_seats(db: AsyncSession, game_id) -> int:
    return (await db.execute(text("""
        SELECT COUNT(*) FROM spectate_leases
         WHERE game_id = :gid AND revoked_at IS NULL
           AND heartbeat_expires_at > NOW()
    """), {"gid": str(game_id)})).scalar() or 0


async def _spectate_record_drains(db: AsyncSession, game, all_leases: bool = False) -> None:
    """Persist authorization-ended occupants before their game row can vanish."""
    gid = (game.get("game_id") or game.get("id")) if hasattr(game, "get") else game["id"]
    await db.execute(text("""
        INSERT INTO spectate_drain_tombstones
            (room_name, region, ghost_steam_id, created_at)
        SELECT :room, :region, l.spectator_steam_id, clock_timestamp()
          FROM spectate_leases l
         WHERE l.game_id = :gid
           AND (:all_leases OR l.revoked_at IS NOT NULL OR l.heartbeat_expires_at <= NOW())
        ON CONFLICT (room_name, region, ghost_steam_id) DO NOTHING
    """), {"room": game["room_name"], "region": game["room_region"] or "",
            "gid": str(gid), "all_leases": bool(all_leases)})


async def _spectate_admission(
    db: AsyncSession,
    game,
    requester_steam_id: str | None = None,
    broadcast: bool = False,
) -> dict:
    """One requester-aware seat predicate shared by listing, grant and target."""
    row = (await db.execute(text("""
        WITH lease_rows AS (
            SELECT spectator_steam_id AS steam_id,
                   (revoked_at IS NULL AND heartbeat_expires_at > NOW()) AS live,
                   LEAST(heartbeat_expires_at,
                         COALESCE(revoked_at, heartbeat_expires_at)) AS ended_at
              FROM spectate_leases
             WHERE game_id = :gid
        ), tomb_rows AS (
            SELECT ghost_steam_id AS steam_id, created_at
              FROM spectate_drain_tombstones
             WHERE room_name = :room AND region = :region
        ), occupied AS (
            SELECT steam_id FROM lease_rows
            UNION
            SELECT steam_id FROM tomb_rows
        ), occupied_windowed AS (
            -- Phase-1 semantics (SPECTATE_DRAIN_ENFORCEMENT=False): an ended
            -- seat consumes capacity only within the bounded drain window, so
            -- an inventory-less ghost self-expires instead of deadlocking the
            -- game's public admission (cold review H2).
            SELECT steam_id FROM lease_rows
             WHERE live OR ended_at > NOW() - make_interval(secs => :drain_seconds)
            UNION
            SELECT steam_id FROM tomb_rows
             WHERE created_at > NOW() - make_interval(secs => :drain_seconds)
        ), active_public AS (
            SELECT DISTINCT spectator_steam_id AS steam_id
              FROM spectate_leases
             WHERE game_id = :gid AND revoked_at IS NULL
               AND heartbeat_expires_at > NOW()
               AND NOT (spectator_steam_id = ANY(CAST(:service_ids AS text[])))
        ), stale_drains AS (
            SELECT spectator_steam_id AS steam_id
              FROM spectate_leases
             WHERE game_id = :gid
               AND (revoked_at <= NOW() - make_interval(secs => :drain_seconds)
                    OR heartbeat_expires_at <= NOW() - make_interval(secs => :drain_seconds))
            UNION
            SELECT ghost_steam_id AS steam_id
              FROM spectate_drain_tombstones
             WHERE room_name = :room AND region = :region
               AND created_at <= NOW() - make_interval(secs => :drain_seconds)
        )
        SELECT
            (SELECT COUNT(*) FROM active_public
              WHERE CAST(:requester AS text) IS NULL
                 OR steam_id <> CAST(:requester AS text)) AS public_active,
            (SELECT COUNT(*) FROM occupied
              WHERE CAST(:requester AS text) IS NULL
                 OR steam_id <> CAST(:requester AS text)) AS physical_occupied,
            (SELECT COUNT(*) FROM occupied_windowed
              WHERE CAST(:requester AS text) IS NULL
                 OR steam_id <> CAST(:requester AS text)) AS physical_occupied_windowed,
            (SELECT COUNT(*) FROM stale_drains
              WHERE (CAST(:requester AS text) IS NULL
                     OR steam_id <> CAST(:requester AS text))
                AND NOT (steam_id = ANY(CAST(:service_ids AS text[])))) AS stale_public,
            (SELECT COUNT(*) FROM stale_drains
              WHERE (CAST(:requester AS text) IS NULL
                     OR steam_id <> CAST(:requester AS text))
                AND steam_id = ANY(CAST(:service_ids AS text[]))) AS stale_broadcast
    """), {"gid": str(game["id"]), "room": game["room_name"],
            "region": game["room_region"] or "", "requester": requester_steam_id,
            "service_ids": sorted(SPECTATE_BROADCAST_STEAM_IDS),
            "drain_seconds": SPECTATE_DRAIN_SECONDS})).mappings().one()
    public_cap = min(int(game["spectator_cap"] or SPECTATE_SEAT_CAP), 4)
    headroom = max(0, int(game["room_capacity"] or 0) - int(game["fighter_target"] or 0))
    # H2 gate: strict occupancy + stale-drain conjuncts apply only once the
    # phase-2 client can actually clear ghosts (see SPECTATE_DRAIN_ENFORCEMENT).
    if SPECTATE_DRAIN_ENFORCEMENT:
        occupied_count = int(row["physical_occupied"])
        stale_pub_block = int(row["stale_public"]) != 0
        stale_bc_block = int(row["stale_broadcast"]) != 0
    else:
        occupied_count = int(row["physical_occupied_windowed"])
        stale_pub_block = False
        stale_bc_block = False
    public_ok = (int(row["public_active"]) < public_cap
                 and occupied_count < headroom
                 and not stale_pub_block)
    broadcast_ok = (occupied_count < headroom
                    and not stale_bc_block)
    return {
        "allowed": broadcast_ok if broadcast else public_ok,
        "public_active": int(row["public_active"]),
        "public_cap": public_cap,
        "physical_occupied": occupied_count,
        "physical_headroom": headroom,
        "stale_drain_blocked": (stale_bc_block if broadcast else stale_pub_block),
    }


# Single-worker module state (#125): one broadcast controller, one sticky
# rotation clock. A restart may cause one early switch, which is benign.
_broadcast_rotation = {
    "incarnation": None,
    "selected_at": 0.0,
    "activated_at": None,
    "last_progress_at": 0.0,
    "acq_ticket": None,
    "acq_phase": None,
    "last_shown": {},
}


def _broadcast_incarnation(game) -> str:
    # `started_at` is the server-owned attestation generation for this game
    # row. A reused room gets a new row id/start stamp, so old exclusions do
    # not suppress the later sitting.
    started = game["started_at"]
    generation = int(started.timestamp() * 1000) if started else 0
    return f"{game['id']}.{generation}"


def _broadcast_exclusions(raw: str | None) -> set[str]:
    if not raw:
        return set()
    out = set()
    for item in raw.split(",")[:BROADCAST_EXCLUSION_MAX]:
        try:
            incarnation, _reason, ttl_raw = item.rsplit(":", 2)
            ttl = max(0, min(int(ttl_raw), BROADCAST_EXCLUSION_TTL_SECONDS))
        except (ValueError, TypeError):
            continue
        if incarnation and ttl > 0:
            out.add(incarnation)
    return out


async def _broadcast_tournament_display(db: AsyncSession, mode: str,
                                        source_ref, roster: list) -> bool:
    """DISPLAY-ONLY tournament classification for a broadcast candidate
    (bug 250). `_spectate_mandatory_class` is an AUTHORIZATION predicate
    (opt-out bypass) and is deliberately narrow — sync + sct- room +
    ready/scheduled only — so active, async, and code-room tournament games
    all rendered as plain "Ranked 1v1" in the stream posts and titles. This
    resolver answers the weaker display question "is this game part of a
    tournament series?" and must NEVER feed an authorization decision.

    Resolution ladder (mirrors _stream_series_score's identity rules — keep
    the two consistent, #330): (1) a resolvable source_ref is TERMINAL —
    direct series id, or one hop via tournament_matches.id; resolving to a
    non-tournament series answers False, never falls through. (2) Only an
    UNRESOLVED reference may use the pair fallback: an active, non-
    invalidated tournament series between the exact pair — async tournament
    reports bind by player pair (any room), so a code-room game between a
    pair holding an open tournament match is that tournament's game by the
    server's own binding semantics."""
    if mode != "1v1":
        return False
    if source_ref:
        try:
            src_uuid = UUID(str(source_ref))
        except Exception:
            src_uuid = None
        if src_uuid is not None:
            row = (await db.execute(text("""
                SELECT rs.is_tournament AS it
                  FROM ranked_series rs
                 WHERE rs.id = :sid
                    OR rs.id = (SELECT tm.series_id
                                  FROM tournament_matches tm
                                 WHERE tm.id = :sid)
                 LIMIT 1
            """), {"sid": src_uuid})).mappings().first()
            if row is not None:
                return bool(row["it"])
    if len(roster) != 2:
        return False
    # Pair fallback, ASYNC-scoped (r1 finding 9): async tournament reports
    # bind by player pair in any room, so a code-room game between a pair
    # holding an OPEN async match is that tournament's game by the server's
    # own binding semantics. Sync tournaments bind by sct- room (the
    # source_ref/mandatory paths above) — a sync pair playing an ordinary
    # code-room game during a break must NOT get tournament treatment, and
    # a forfeited match whose series row lingers 'active' must not either
    # (#350's terminal-status arm).
    hit = (await db.execute(text("""
        SELECT 1
          FROM ranked_series rs
          JOIN players p1 ON p1.id = rs.player1_id
          JOIN players p2 ON p2.id = rs.player2_id
          JOIN tournament_matches tm ON tm.series_id = rs.id
          JOIN tournaments t ON t.id = tm.tournament_id
         WHERE rs.status = 'active' AND rs.invalidated_at IS NULL
           AND rs.is_tournament
           AND t.kind = 'async' AND t.status = 'running'
           AND tm.status NOT IN ('completed', 'forfeit',
                                 'double_forfeit', 'bye_auto')
           AND ((p1.steam_id = :a AND p2.steam_id = :b)
             OR (p1.steam_id = :b AND p2.steam_id = :a))
         LIMIT 1
    """), {"a": roster[0], "b": roster[1]})).scalar()
    return bool(hit)


async def _broadcast_candidate(db: AsyncSession, game, requester: str) -> dict | None:
    ready, _reason = await _spectate_game_ready(db, game)
    if not ready or game["mode"] not in _SPECTATE_WATCHABLE_MODES:
        return None
    admission = await _spectate_admission(
        db, game, requester_steam_id=requester, broadcast=True)
    if not admission["allowed"]:
        return None

    roster = _spectate_roster_list(game["roster"])
    if not roster:
        return None
    rows = (await db.execute(text("""
        SELECT p.steam_id, p.display_name,
               CASE
                 WHEN :mode = '2v2' THEN COALESCE(g2.rating, 1500)
                 WHEN :mode = 'ffa' THEN COALESCE(gf.rating, 1500)
                 ELSE COALESCE(g1.rating, 1500)
               END AS rating
          FROM players p
          LEFT JOIN glicko_ratings g1 ON g1.player_id = p.id
          LEFT JOIN glicko_ratings_2v2 g2 ON g2.player_id = p.id
          LEFT JOIN glicko_ratings_ffa gf ON gf.player_id = p.id
         WHERE p.steam_id = ANY(CAST(:sids AS text[]))
    """), {"mode": game["mode"], "sids": roster})).mappings().all()
    by_sid = {r["steam_id"]: r for r in rows}
    ratings = [float(by_sid[s]["rating"]) if s in by_sid else 1500.0 for s in roster]
    names = [(by_sid[s]["display_name"] or "?") if s in by_sid else "?" for s in roster]
    mandatory = await _spectate_mandatory_class(db, game)
    # Bug 250: is_tournament is a DISPLAY field (stream post lines, titles,
    # the 🏆 prefix) — resolve it for every tournament game, not only the
    # mandatory-class ones. `tier` stays driven by the strict authorization
    # classifier: display accuracy must not widen the opt-out bypass.
    is_tourn = bool(mandatory) or await _broadcast_tournament_display(
        db, game["mode"], game["source_ref"], roster)
    return {
        "game_id": str(game["id"]),
        "incarnation": _broadcast_incarnation(game),
        "mode": game["mode"],
        "source_ref": game["source_ref"],
        "is_tournament": is_tourn,
        "tier": 1 if mandatory else 2,
        "score": float(sum(ratings)),
        "names": names,
        "ratings": [round(v, 1) for v in ratings],
        "phase": game["phase"],
        # INTERNAL (never in _broadcast_public): roster steam ids in the SAME
        # order as names — the stream post's series-score lookup binds its
        # side order to this (review F1).
        "roster_sids": roster,
    }


def _broadcast_public(candidate: dict) -> dict:
    return {k: candidate[k] for k in (
        "game_id", "incarnation", "mode", "source_ref", "is_tournament",
        "score", "names", "ratings", "phase")}


async def _spectate_authoritative_roster(db: AsyncSession, mode: str, room: str):
    """Resolve the room's TRUE roster + source id from the server's own
    queue-lock records (Codex r1 find 5: a caller-authored roster lets two
    colluding sessions list someone else's real room and bypass a third
    player's opt-out). Returns (steam_id_set_or_None, source_ref).
    None = no server mapping exists for this mode/room (1v1 fallback);
    an EMPTY set = a mapping SHOULD exist and does not -> fail closed."""
    if mode == "2v2":
        row = (await db.execute(text("""
            SELECT ts.id,
                   (SELECT array_agg(p.steam_id) FROM players p
                     WHERE p.id IN (ts.t1a_id, ts.t1b_id, ts.t2a_id, ts.t2b_id)) AS sids
              FROM team_series ts
             WHERE ts.photon_room_id = :room AND ts.completed_at IS NULL
               AND ts.invalidated_at IS NULL
             ORDER BY ts.created_at DESC LIMIT 1
        """), {"room": room})).mappings().first()
        if row is None or not row["sids"]:
            return set(), ""
        return set(row["sids"]), str(row["id"])
    if mode == "1v2":
        row = (await db.execute(text("""
            SELECT s.id,
                   (SELECT array_agg(p.steam_id) FROM players p
                     WHERE p.id IN (s.solo_id, s.duo_a_id, s.duo_b_id)) AS sids
              FROM ovt_series s
             WHERE s.photon_room_id = :room
               AND s.status IN ('active', 'dc_paused', 'dc_incomplete')
             ORDER BY s.created_at DESC LIMIT 1
        """), {"room": room})).mappings().first()
        if row is None or not row["sids"]:
            return set(), ""
        return set(row["sids"]), str(row["id"])
    if mode == "ffa":
        # LIVE membership = locked members minus departed (Codex r2 find 5:
        # a bare subset test let two colluding members attest a 2-man roster
        # for a 6-player lobby and dodge the other four's opt-outs). The
        # attest handler requires the claimed roster to EQUAL this set.
        row = (await db.execute(text("""
            SELECT l.id,
                   (SELECT array_agg(p.steam_id) FROM players p
                     WHERE p.id = ANY(l.member_ids)
                       AND NOT (p.id = ANY(COALESCE(l.departed_ids, '{}')))) AS sids
              FROM ffa_lobbies l
             WHERE l.photon_room_id = :room AND l.status = 'active'
             ORDER BY l.created_at DESC LIMIT 1
        """), {"room": room})).mappings().first()
        if row is None or not row["sids"]:
            return set(), ""
        return set(row["sids"]), str(row["id"])
    if room.startswith("sct-"):
        # Sync tournament rooms have an authoritative mapping BY CONSTRUCTION
        # (the dispatch stamps photon_room_name on the bracket match), so —
        # unlike code rooms — they never get fallback trust: no live mapping
        # under a running tournament = fail closed (Codex tournament-batch r1
        # find 3's condition for accepting the prefix at all).
        row = (await db.execute(text("""
            SELECT tm.id, q1.steam_id AS a, q2.steam_id AS b
              FROM tournament_matches tm
              JOIN tournaments t ON t.id = tm.tournament_id
              JOIN tournament_signups s1 ON s1.id = tm.p1_signup_id
              JOIN tournament_signups s2 ON s2.id = tm.p2_signup_id
              JOIN players q1 ON q1.id = s1.player_id
              JOIN players q2 ON q2.id = s2.player_id
             WHERE tm.photon_room_name = :room
               AND tm.status NOT IN ('completed','forfeit','double_forfeit','bye_auto')
               AND t.status = 'running'
             ORDER BY tm.round DESC LIMIT 1
        """), {"room": room})).mappings().first()
        if row is None or not row["a"] or not row["b"]:
            return set(), ""
        return {row["a"], row["b"]}, str(row["id"])
    # 1v1: ranked queue rows may already be pruned by report time; when they
    # exist, enforce them, else accept cardinality+session only (documented
    # residual: two colluding SESSIONS can list a ranked_ room name they
    # already know — the room name is the credential either way, §6.6).
    rows = (await db.execute(text("""
        SELECT p.steam_id FROM ranked_queue q JOIN players p ON p.id = q.player_id
         WHERE q.room_name = :room
    """), {"room": room})).mappings().all()
    # Enforce only a COMPLETE pair — queue rows are pruned asymmetrically
    # after lock, and a lone survivor row must not brick attestation with an
    # exact-equality check it can never satisfy.
    if len(rows) == 2:
        return {r["steam_id"] for r in rows}, ""
    return None, ""


# Per-mode exact fighter cardinality (Codex r1 find 5: without this, two
# attesters could declare a team_ room a 2-fighter game).
_SPECTATE_MODE_TARGET = {"1v1": 2, "2v2": 4, "1v2": 3}


@app.post("/api/v1/spectate/participant-attest", tags=["Spectate"])
async def spectate_participant_attest(req: SpectateAttestBody, request: Request,
                                      db: AsyncSession = Depends(get_db)):
    if req.mode not in _SPECTATE_MODES:
        raise HTTPException(status_code=422, detail="bad_mode")
    if req.mode == "1v1":
        # 1v1 accepts CODE rooms too (Sid, Aug 7: private ranked lobbies are
        # most real ranked play, #286) — but a 1v1 claim must never wear a
        # TEAM-mode prefix (cross-mode masquerade would dodge the stricter
        # modes' roster verification). Collusion residual is the documented
        # 1v1 fallback one (§6.6): two sessions can list a room name they
        # already possess; the room name is the credential either way,
        # capacity gating fails the lure onto full vanilla rooms, and modded
        # victims classify-and-suppress the entrant.
        #
        # sct- (sync tournament) rooms ARE 1v1 rooms and are accepted here
        # since the tournament batch (Codex r1 find 3: rejecting the prefix
        # made mandatory tournament spectating structurally unreachable for
        # sync tournaments). Unlike code rooms they get NO fallback trust:
        # _spectate_authoritative_roster resolves the TRUE pair from the
        # tournament match's own photon_room_name and fails closed when no
        # running-tournament mapping exists.
        if any(req.room_name.startswith(p) for p in ("team_", "ovt_", "ffa_")):
            raise HTTPException(status_code=422, detail="room_mode_mismatch")
    elif not req.room_name.startswith(_SPECTATE_ROOM_PREFIX[req.mode]):
        raise HTTPException(status_code=422, detail="room_mode_mismatch")
    roster = _spectate_roster_list(req.roster)
    if len(roster) != req.fighter_target or req.steam_id not in roster:
        raise HTTPException(status_code=422, detail="bad_roster")
    if sorted(roster) != roster or len(set(roster)) != len(roster):
        raise HTTPException(status_code=422, detail="roster_not_canonical")
    if req.mode in _SPECTATE_MODE_TARGET:
        if req.fighter_target != _SPECTATE_MODE_TARGET[req.mode]:
            raise HTTPException(status_code=422, detail="bad_cardinality")
    elif not (2 <= req.fighter_target <= 10):   # ffa (2 tolerates leavers mid-sitting)
        raise HTTPException(status_code=422, detail="bad_cardinality")
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    await _assert_no_service_subject(db, affected_steam_ids=[req.steam_id])

    # Server-authoritative roster check (fail CLOSED when a mapping should
    # exist): the claimed roster must be members of the room's real locked
    # group, and the claimed room must actually belong to this mode's flow.
    true_roster, derived_ref = await _spectate_authoritative_roster(db, req.mode, req.room_name)
    if true_roster is not None:
        if not true_roster:
            raise HTTPException(status_code=409, detail="room_unknown")
        # EXACT set equality (Codex r2 find 5): a proper subset would let a
        # partial clique attest around the excluded members' opt-outs.
        if set(roster) != true_roster or req.steam_id not in true_roster:
            raise HTTPException(status_code=409, detail="roster_mismatch")
    await _assert_no_service_subject(db, affected_steam_ids=roster)

    # Serialize per-room (attests from all fighters land within the same
    # second) — advisory lock on the room name, then upsert game + attest.
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:k))"),
                     {"k": f"spectate:{req.room_name}"})
    game = (await db.execute(text("""
        SELECT id, roster, room_name, room_region FROM spectate_games
         WHERE room_name = :room AND ended_at IS NULL
    """), {"room": req.room_name})).mappings().first()
    is_battle = req.phase == "battle"
    if game is None:
        gid = str(uuid.uuid4())
        await db.execute(text("""
            INSERT INTO spectate_games
                (id, mode, source_ref, room_name, room_region, roster,
                 fighter_target, room_capacity, spectator_cap, protocol_min, phase,
                 last_battle_at)
            VALUES (CAST(:id AS UUID), :mode, :ref, :room, :region, :roster,
                    :target, :cap, :seats, :proto, :phase,
                    CASE WHEN :battle THEN NOW() ELSE NOW() - INTERVAL '1 hour' END)
            ON CONFLICT (room_name) WHERE ended_at IS NULL DO NOTHING
        """), {"id": gid, "mode": req.mode, "ref": derived_ref[:64],
               "room": req.room_name, "region": req.region, "roster": req.roster,
               "target": req.fighter_target, "cap": req.room_capacity,
               "seats": SPECTATE_SEAT_CAP, "proto": SPECTATE_PROTOCOL,
               "phase": req.phase[:16], "battle": is_battle})
        game = (await db.execute(text("""
            SELECT id, roster FROM spectate_games
             WHERE room_name = :room AND ended_at IS NULL
        """), {"room": req.room_name})).mappings().first()
        if game is None:
            raise HTTPException(status_code=500, detail="attest_race")
    else:
        # Last-writer-wins on the live tuple: completeness (checked at list/
        # grant time) is what enforces agreement, so a roster change (FFA
        # leaver) converges as the remaining fighters re-attest.
        # source_ref is server-derived, never the caller's (r1 find 4).
        # protocol_min ADVANCES on refresh (Aug 10 blocker 3: it used to be
        # frozen at create time, so a live row from before a protocol bump
        # kept admitting old-protocol pairings forever). GREATEST only — a
        # rollback deploy must not lower a row's floor under seated leases.
        await db.execute(text("""
            UPDATE spectate_games
               SET roster = :roster, room_region = :region, phase = :phase,
                   fighter_target = :target, room_capacity = :cap,
                   source_ref = :ref,
                   protocol_min = GREATEST(protocol_min, :proto),
                   last_attest_at = NOW(),
                   last_battle_at = CASE WHEN :battle THEN NOW() ELSE last_battle_at END
             WHERE id = :gid
        """), {"roster": req.roster, "region": req.region, "phase": req.phase[:16],
               "target": req.fighter_target, "cap": req.room_capacity,
               "ref": derived_ref[:64], "battle": is_battle,
               "proto": SPECTATE_PROTOCOL,
               "gid": str(game["id"])})

    await db.execute(text("""
        INSERT INTO spectate_attestations
            (game_id, steam_id, actor_number, region, fighter_target,
             room_capacity, protocol, roster, phase, attested_at)
        VALUES (:gid, :sid, :actor, :region, :target, :cap, :proto, :roster, :phase, NOW())
        ON CONFLICT (game_id, steam_id) DO UPDATE SET
            actor_number = EXCLUDED.actor_number,
            region = EXCLUDED.region,
            fighter_target = EXCLUDED.fighter_target,
            room_capacity = EXCLUDED.room_capacity,
            protocol = EXCLUDED.protocol,
            roster = EXCLUDED.roster,
            phase = EXCLUDED.phase,
            attested_at = NOW()
    """), {"gid": str(game["id"]), "sid": req.steam_id, "actor": req.actor_number,
           "region": req.region, "target": req.fighter_target,
           "cap": req.room_capacity, "proto": req.spectator_protocol,
           "roster": req.roster, "phase": req.phase[:16]})
    await db.commit()
    return {"status": "ok"}


@app.post("/api/v1/spectate/close", tags=["Spectate"])
async def spectate_close(req: SpectateCloseBody, request: Request,
                         db: AsyncSession = Depends(get_db)):
    """A fighter has left the room — retract their attestation, and end the
    game row once nobody is still attesting.

    WHY (bug 199 adjacent finding, Aug 11): nothing ever wrote
    spectate_games.ended_at, so a finished match stayed "live" until its
    last_attest_at aged past SPECTATE_ATTEST_FRESH_SECONDS. Fighters simply
    stop attesting when they leave, so for up to 150 seconds the games list
    kept advertising a room Photon had already destroyed — Sid clicked one
    twice on Aug 11 and got 'Photon join refused (32758): Game does not exist'
    both times. This collapses that window to the length of one HTTP call.

    SAFE BY CONSTRUCTION: the caller may only retract its OWN attestation, and
    the row is ended only when no other fighter is still fresh. A modified
    client therefore cannot close a match it is not in (403), nor one whose
    other fighters are still playing — an FFA leaver does not end the game for
    the survivors (#222). Idempotent: closing an already-closed room is 200.
    """
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    # Same advisory lock key the attest path uses, so a close racing a
    # concurrent attest from another fighter serializes instead of
    # interleaving the retract with someone else's refresh.
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:k))"),
                     {"k": f"spectate:{req.room_name}"})
    game = (await db.execute(text("""
        SELECT id, roster, room_name, room_region FROM spectate_games
         WHERE room_name = :room AND ended_at IS NULL
    """), {"room": req.room_name})).mappings().first()
    if game is None:
        # Already closed, or never attested. Nothing to do — and deliberately
        # NOT a 404: the client fires this on every room leave, including
        # rooms that never became spectatable at all.
        return {"status": "ok", "closed": False}
    if req.steam_id not in _spectate_roster_list(game["roster"]):
        raise HTTPException(status_code=403, detail="not_a_participant")
    await _assert_no_service_subject(
        db, affected_steam_ids=_spectate_roster_list(game["roster"]))
    await db.execute(text("""
        DELETE FROM spectate_attestations
         WHERE game_id = :gid AND steam_id = :sid
    """), {"gid": str(game["id"]), "sid": req.steam_id})
    _remaining = (await db.execute(text("""
        SELECT COUNT(*) FROM spectate_attestations
         WHERE game_id = :gid
           AND attested_at > NOW() - make_interval(secs => :fresh)
    """), {"gid": str(game["id"]),
           "fresh": SPECTATE_ATTEST_FRESH_SECONDS})).scalar() or 0
    _closed = False
    if _remaining == 0:
        # Ending the database row ends every lease's authorization, but it is
        # not evidence that those Photon actors left the reusable room.
        await _spectate_record_drains(db, game, all_leases=True)
        await db.execute(text("""
            UPDATE spectate_games SET ended_at = NOW()
             WHERE id = :gid AND ended_at IS NULL
        """), {"gid": str(game["id"])})
        _closed = True
    await db.commit()
    if _closed:
        # Log the game id, NEVER the room name — the room name IS the join
        # credential and this module's header states unqualified that it never
        # reaches a log (design §6.4). This was the only site in main.py that
        # would have broken that invariant.
        print(f"[SPECTATE] game {game['id']} closed on last fighter leave")
    return {"status": "ok", "closed": _closed}


@app.get("/api/v1/spectate/games", tags=["Spectate"])
async def spectate_games(db: AsyncSession = Depends(get_db)):
    """Public spectatable-games list. NO room credentials in the response
    (design §6.4) — game_id is the only handle a client ever needs."""
    games = (await db.execute(text("""
        SELECT id, mode, source_ref, room_name, room_region, roster,
               fighter_target, room_capacity, spectator_cap, protocol_min, phase,
               last_battle_at
          FROM spectate_games
         WHERE ended_at IS NULL
           AND last_attest_at > NOW() - make_interval(secs => :fresh)
         ORDER BY started_at DESC
         LIMIT 30
    """), {"fresh": SPECTATE_ATTEST_FRESH_SECONDS})).mappings().all()
    # Player/title metadata stays batched. Readiness, mandatory classification,
    # and physical-seat admission are intentionally per game because all three
    # are shared authorization predicates, not display-only approximations.
    all_sids = sorted({s for g in games for s in _spectate_roster_list(g["roster"])})
    meta_by_sid: dict = {}
    if all_sids:
        rows = (await db.execute(text("""
            SELECT p.steam_id, p.display_name, p.id::text AS player_id,
                   p.allow_spectators,
                   COALESCE(gr.rating, 1500) AS rating,
                   si.name AS title, si.preview_color AS title_color,
                   si.sku AS title_sku
              FROM players p
              LEFT JOIN glicko_ratings gr ON gr.player_id = p.id
              LEFT JOIN shop_items si ON si.id = p.active_title_id
             WHERE p.steam_id = ANY(:sids)
        """), {"sids": all_sids})).mappings().all()
        meta_by_sid = {r["steam_id"]: r for r in rows}
    _colors = await _rank_colors(db)
    _pmap, _pmap2, _pmapf = await _podium_maps_for(
        db, (m["title_sku"] for m in meta_by_sid.values()))
    async def _ready_batched(g) -> tuple[bool, str]:
        """_spectate_game_ready with the players half prefetched — same
        rules, one attest query instead of three queries per game."""
        roster0 = _spectate_roster_list(g["roster"])
        if len(roster0) != g["fighter_target"]:
            return False, "room_not_ready"
        if g["room_capacity"] < g["fighter_target"] + 1:
            return False, "room_not_ready"
        lba = g["last_battle_at"]
        if lba is None or lba < datetime.now(timezone.utc) - timedelta(seconds=SPECTATE_ATTEST_FRESH_SECONDS):
            return False, "room_not_ready"
        arows = (await db.execute(text("""
            SELECT steam_id, roster, region, fighter_target, room_capacity, protocol
              FROM spectate_attestations
             WHERE game_id = :gid
               AND attested_at > NOW() - make_interval(secs => :fresh)
        """), {"gid": str(g["id"]), "fresh": SPECTATE_ATTEST_FRESH_SECONDS})).mappings().all()
        a_by_sid = {r["steam_id"]: r for r in arows}
        _opted_out = False
        for s in roster0:
            a = a_by_sid.get(s)
            if a is None:
                return False, "room_not_ready"
            if (a["roster"] != g["roster"] or a["region"] != g["room_region"]
                    or a["fighter_target"] != g["fighter_target"]
                    or a["room_capacity"] != g["room_capacity"]
                    # max(stored, constant) — r3 blocker 1, same as above.
                    or a["protocol"] < max(g["protocol_min"] or 1, SPECTATE_PROTOCOL)):
                return False, "room_not_ready"
            m = meta_by_sid.get(s)
            if m is None:
                # No player row at all — fail closed, tournament or not.
                return False, "spectating_disabled"
            if not bool(m["allow_spectators"]):
                # Deferred, not an early return: the tournament skip below
                # must mirror _spectate_game_ready's rule exactly (#159 —
                # a list that hides what the grant allows, or shows what it
                # 409s, is the same-predicate bug either way).
                _opted_out = True
        if _opted_out:
            if not await _spectate_mandatory_class(db, g):
                # Generic — never reveal WHICH participant opted out (§6.4).
                return False, "spectating_disabled"
        return True, ""

    out = []
    for g in games:
        ready, reason = await _ready_batched(g)
        # Aug 7 item 13: per-mode watchability flag — see
        # _SPECTATE_WATCHABLE_MODES for why this exists.
        if ready and g["mode"] not in _SPECTATE_WATCHABLE_MODES:
            ready, reason = False, "mode_not_ready"
        admission = await _spectate_admission(db, g)
        seats = admission["public_active"]
        if ready and not admission["allowed"]:
            ready, reason = False, "spectator_full"
        roster = _spectate_roster_list(g["roster"])
        names = []
        titles = []
        title_colors = []
        ratings = []
        for s in roster:
            r = meta_by_sid.get(s)
            if r is None:
                # EVERY list gets an entry here. They are consumed positionally
                # against the roster, so skipping one in this branch shifts
                # every later player's title/colour onto the wrong person.
                names.append("?"); titles.append(""); title_colors.append("")
                ratings.append("1500")
                continue
            names.append(r["display_name"] or "?")
            # Podium pos included (Codex r5 find 6: title_podium resolved
            # to nothing without it).
            t, _tc = _display_title_sync(_colors, r["title_sku"], r["title"],
                                         r["title_color"], float(r["rating"]),
                                         podium_pos=_pmap.get(r["player_id"]),
                                         podium_pos_2v2=_pmap2.get(r["player_id"]),
                                         podium_pos_ffa=_pmapf.get(r["player_id"]))
            titles.append(t or "")
            # The colour half of the same call, which used to be computed and
            # thrown away — so SpectatorSession.WatchedTitleColors was always
            # empty and the HUD fell back to its grey for every watched player,
            # while every other title surface in the mod renders the title in
            # its own colour (Aug 12 item 9b, closed here).
            # A '|' in a colour would desynchronise the array against
            # roster_titles; hex values cannot contain one (production: 0 of 43
            # title rows have a pipe in name or preview_color), and the strip
            # keeps that true no matter what a future title colour holds.
            title_colors.append((_tc or "").replace("|", ""))
            ratings.append(str(int(r["rating"])))
        out.append({
            "game_id": str(g["id"]),
            "mode": g["mode"],
            "source_ref": g["source_ref"],
            # Pipe-joined, roster-aligned (titles can contain commas; pipes
            # are stripped from display names at ingest).
            "roster_titles": "|".join(titles),
            # Same length and same order as roster_titles, one hex per title
            # ("" where there is no title or no colour). The client tolerates a
            # short/absent array by falling back per entry, so an older client
            # ignores this field rather than breaking on it.
            "roster_title_colors": "|".join(title_colors),
            "roster_ratings": ",".join(ratings),
            # Roster steam ids are public identifiers used across the API;
            # the client matches Live-panel series by them when source_ref
            # is empty (1v1 rooms have no server-side series mapping).
            "roster": g["roster"],
            "phase": g["phase"],
            "names": ", ".join(names),
            "spectator_count": seats,
            # Anonymous listing is deliberately the conservative PUBLIC view;
            # the requester-aware broadcast branch runs only at grant/target.
            "spectator_cap": admission["public_cap"],
            "spectatable": ready,
            "disabled_reason": reason,
        })
    return {"games": out}


# ── Living stream post (#scr-ranked-streaming, Aug 17) ──────────────────
# The VM bot has no credentials by design; the MOD's authenticated
# /broadcast/target poll is the only channel off that machine, so the bot
# writes a stream-state file, the mod folds it into this poll, and the
# server runs the post's state machine in stream_channel_posts (migration
# 226 — revision-acked living post, delivered by the Discord bot).
RANKED_STREAMING_CHANNEL_ID = os.getenv("RANKED_STREAMING_CHANNEL", "1539051213751062649")
BROADCAST_TWITCH_URL = os.getenv("BROADCAST_TWITCH_URL", "https://twitch.tv/sidscompetitiverounds")
BROADCAST_YOUTUBE_URL = os.getenv("BROADCAST_YOUTUBE_URL", "https://youtube.com/@SidsCompetitiveRounds/live")
# A stream post's session goes stale when no stream_live poll has carried it
# for this long (mod polls every 10s while the director runs) — the pending
# GET finalizes it, so delivery drives the janitor and no new loop exists.
# Honest worst-case "ended" lag (review F18): dead-director-while-ROUNDS-
# lives = the mod keeps trusting the stream-info file for its 120s freshness
# window, THEN this interval, THEN up to one 20s bot poll — ~6.5 minutes.
# The premature-finalize direction is recoverable: a live claim for a
# finalized session REOPENS it (review F2).
STREAM_POST_STALE_SECONDS = 240
_STREAM_SESSION_RE = _re.compile(r"^[A-Za-z0-9._-]{1,64}$")
_STREAM_MODE_LABELS = {"1v1": "Ranked 1v1", "2v2": "2v2", "ovt": "1v2", "ffa": "FFA"}

# Direct VOD links (Aug 18, Sid: the ended post must keep its links and point
# at the VOD). Resolved by the VM bot with its own platform creds while the
# stream is LIVE (Twitch mints the archive at broadcast start; the YouTube
# broadcast id IS the video id), carried on this same authenticated poll,
# stored on the post row, and rendered only by the finalize edit. STRICT
# per-platform allowlists — these render as links in an official channel
# post, so anything not exactly a VOD URL is dropped (#159: server-side
# validation is the real gate; the mod's https prefix check is cosmetic).
_STREAM_TVOD_RE = _re.compile(r"^https://www\.twitch\.tv/videos/\d{1,20}$")
_STREAM_YVOD_RE = _re.compile(r"^https://www\.youtube\.com/watch\?v=[A-Za-z0-9_-]{5,20}$")
# Channel-level fallbacks when a session ended before its direct VOD
# resolved (or for pre-feature rows): Twitch's past-broadcasts page and the
# channel's live tab — never a bare "links removed" post again.
BROADCAST_TWITCH_VODS_URL = os.getenv(
    "BROADCAST_TWITCH_VODS_URL", "https://www.twitch.tv/sidscompetitiverounds/videos?filter=archives")
BROADCAST_YOUTUBE_VODS_URL = os.getenv(
    "BROADCAST_YOUTUBE_VODS_URL", "https://youtube.com/@SidsCompetitiveRounds/streams")


def _stream_ended_content(twitch_vod: str | None, youtube_vod: str | None,
                          matchups: list | None = None) -> str:
    """The finalize body: thanks line + VOD links (direct when the session
    resolved them, channel archive pages otherwise) + the session's matchup
    list (Sid, Aug 18: players need to see WHICH matches a VOD covers to
    find their own games). Composed in Python at each finalize site so the
    sites can never drift (#330). Matchup lines are stored pre-escaped by
    the upkeep path; the render budget stays far under the bot's 3900-char
    embed slice so the links can never be pushed out."""
    t = twitch_vod or BROADCAST_TWITCH_VODS_URL
    y = youtube_vod or BROADCAST_YOUTUBE_VODS_URL
    body = ("The stream has ended - thanks for watching!\n"
            f"🎬 Twitch VOD: {t}\n"
            f"▶️ YouTube VOD: {y}")
    lines = [str(m) for m in (matchups or []) if str(m).strip()]
    if lines:
        shown = []
        budget = 1500
        for line in lines:
            if len(shown) >= 20 or len(line) + 3 > budget:
                break
            shown.append(line)
            budget -= len(line) + 3
        body += "\n\nMatches this stream:\n" + "\n".join(f"• {ln}" for ln in shown)
        if len(lines) > len(shown):
            body += f"\n…and {len(lines) - len(shown)} more"
    return body


def _stream_mode_label(candidate: dict) -> str:
    """Bug 250: THE mode label for stream surfaces — one helper for both the
    live body and the stored matchup line (#330). A tournament 1v1 says so
    in the text itself; the 🏆 prefix alone left the line reading
    "Ranked 1v1" for every tournament game."""
    mode = _STREAM_MODE_LABELS.get(candidate.get("mode") or "",
                                   candidate.get("mode") or "?")
    if candidate.get("is_tournament") and (candidate.get("mode") or "") == "1v1":
        return "Tournament 1v1"
    return mode


def _stream_matchup_line(candidate: dict | None) -> str:
    """One display line identifying a watched matchup — names + elo + mode,
    deliberately NO score (a score change must not mint a second entry for
    the same match). Same escaping as the live line; empty when there is no
    candidate."""
    if candidate is None:
        return ""
    names = candidate.get("names") or []
    ratings = candidate.get("ratings") or []
    def _nm(i):
        n = _stream_md_escape(str(names[i])[:24]) if i < len(names) else "?"
        try:
            r = int(ratings[i]) if i < len(ratings) else 0
        except Exception:
            r = 0
        return f"**{n}** ({r})" if r > 0 else f"**{n}**"
    mode = _stream_mode_label(candidate)
    if len(names) == 2:
        vs = f"{_nm(0)} vs {_nm(1)}"
    else:
        vs = ", ".join(_nm(i) for i in range(len(names))) or "?"
    line = f"{vs} - {mode}"
    if candidate.get("is_tournament"):
        line = "🏆 " + line
    return line[:200]


def _stream_md_escape(s: str) -> str:
    """Names go into a Discord embed body — neutralize markdown metacharacters
    (embeds never ping, and the bot sends AllowedMentions.none(), so mention
    tokens are cosmetic-only here). Brackets/parens/angles included (review
    F10): AllowedMentions suppresses pings, NOT hyperlinks, and a name like
    "[watch](https://evil)" would otherwise render a clickable link in an
    official embed. Round-2 finding 5: whitespace/control chars collapse to
    single spaces (a newline in a name forges whole embed LINES) and bare
    URLs get a zero-width space after the scheme so Discord's auto-linker
    never fires on caller-authored text."""
    collapsed = " ".join((s or "").split())
    out = []
    for ch in collapsed:
        if ch in "*_~`|\\[]()<>":
            out.append("\\")
        out.append(ch)
    escaped = "".join(out)
    return _re.sub(r"(?i)(https?):(/{1,2})", "\\1:\u200b\\2", escaped)


async def _stream_series_score(db: AsyncSession, candidate: dict | None) -> str | None:
    """SERVER-derived 1v1 series tally oriented to the candidate's own
    names/roster order (review F1: the mod-computed score carried neither the
    game's identity nor a side-order contract, so it could render reversed or
    against the wrong pair entirely). None for non-1v1 modes and when no
    series matches — the post simply omits the tally.

    Series identity (round-2 finding 4): when the spectate game's source_ref
    IS a series id, bind to that exact row — a pair can hold TWO active
    series at once (tournament + queue resume) and pair+recency alone can
    display the other one's score under the watched match's names.
    Invalidated rows are excluded in both arms (an admin-reversed series can
    remain status='active')."""
    try:
        if not candidate or candidate.get("mode") != "1v1":
            return None
        sids = candidate.get("roster_sids") or []
        if len(sids) != 2:
            return None
        row = None
        src = candidate.get("source_ref")
        if src:
            try:
                src_uuid = UUID(str(src))
            except Exception:
                src_uuid = None
            if src_uuid is not None:
                # source_ref is NOT uniformly a series id (round-3 f2): sync
                # tournament attestation stores tournament_matches.id, whose
                # series lives one hop away at tm.series_id; queue 1v1 rooms
                # may store the series id directly; code rooms store nothing.
                # A RESOLVED source is TERMINAL either way (round-4 f2): when
                # it resolves to an invalidated series, the honest answer is
                # "no tally" — falling through to the pair lookup rendered a
                # DIFFERENT active series' score under the watched match's
                # names. Only an UNRESOLVED reference may use the fallback.
                row = (await db.execute(text("""
                    SELECT rs.p1_series_wins AS w1, rs.p2_series_wins AS w2,
                           p1.steam_id AS s1, rs.invalidated_at AS inv
                      FROM ranked_series rs
                      JOIN players p1 ON p1.id = rs.player1_id
                      JOIN players p2 ON p2.id = rs.player2_id
                     WHERE rs.id = :sid
                        OR rs.id = (SELECT tm.series_id
                                      FROM tournament_matches tm
                                     WHERE tm.id = :sid)
                     LIMIT 1
                """), {"sid": src_uuid})).mappings().first()
                if row is not None and row["inv"] is not None:
                    return None
        if row is None:
            row = (await db.execute(text("""
                SELECT rs.p1_series_wins AS w1, rs.p2_series_wins AS w2,
                       p1.steam_id AS s1
                  FROM ranked_series rs
                  JOIN players p1 ON p1.id = rs.player1_id
                  JOIN players p2 ON p2.id = rs.player2_id
                 WHERE rs.status = 'active' AND rs.invalidated_at IS NULL
                   AND ((p1.steam_id = :a AND p2.steam_id = :b)
                        OR (p1.steam_id = :b AND p2.steam_id = :a))
                 ORDER BY GREATEST(rs.created_at,
                                   COALESCE(rs.last_activity_at, rs.created_at)) DESC
                 LIMIT 1
            """), {"a": sids[0], "b": sids[1]})).mappings().first()
        if row is None:
            return None
        w1, w2 = int(row["w1"] or 0), int(row["w2"] or 0)
        if row["s1"] != sids[0]:
            w1, w2 = w2, w1
        return f"{w1}-{w2}"
    except Exception as ex:
        print(f"[STREAM-POST] score lookup failed (non-fatal): {ex}")
        return None


def _stream_post_content(candidate: dict | None, score: str | None) -> str:
    """Compose the post BODY (no timestamp — the Discord bot stamps a live
    <t:..:R> at render time so edits don't churn revisions)."""
    if candidate is None:
        line = "Between matches - watching for the next game..."
    else:
        names = candidate.get("names") or []
        ratings = candidate.get("ratings") or []
        def _nm(i):
            n = _stream_md_escape(str(names[i])[:24]) if i < len(names) else "?"
            # Guarded (review F2): a NaN rating (DOUBLE PRECISION permits it)
            # raised here EVERY poll, rolling back the whole upkeep — the
            # post then aged into a false janitor finalize while genuinely
            # live. Malformed rating = render no rating, never throw.
            try:
                r = int(ratings[i]) if i < len(ratings) else 0
            except Exception:
                r = 0
            return f"**{n}** ({r})" if r > 0 else f"**{n}**"
        mode = _stream_mode_label(candidate)
        if len(names) == 2:
            vs = f"{_nm(0)} vs {_nm(1)}"
        else:
            vs = ", ".join(_nm(i) for i in range(len(names))) or "?"
        line = f"Watching: {vs} - {mode}"
        if candidate.get("is_tournament"):
            line = "🏆 " + line
        if score:
            line += f"  [{score}]"
    return (f"{line}\n"
            f"📺 Twitch: {BROADCAST_TWITCH_URL}\n"
            f"▶️ YouTube: {BROADCAST_YOUTUBE_URL}")


async def _stream_post_upkeep(db: AsyncSession, stream_live: int | None,
                              stream_session: str | None,
                              candidate: dict | None,
                              stream_tvod: str | None = None,
                              stream_yvod: str | None = None) -> None:
    """State machine for the living stream post. Commits its own writes —
    the surrounding poll handler is otherwise read-only. Never raises: the
    poll's real job (the director) must not fail over a Discord nicety
    (#187 family)."""
    if not stream_live or not stream_session:
        return
    if not _STREAM_SESSION_RE.match(stream_session):
        return
    # VOD links: strict allowlist or nothing (they render in an official
    # embed at finalize). Stored on every live branch via COALESCE — once
    # known they stick, so a mod restart polling without them cannot erase.
    tvod = stream_tvod if stream_tvod and _STREAM_TVOD_RE.match(stream_tvod) else None
    yvod = stream_yvod if stream_yvod and _STREAM_YVOD_RE.match(stream_yvod) else None
    try:
        # A live claim for session K SUPERSEDES every other session (round-2
        # finding 1): the VM runs exactly one stream at a time, so any other
        # un-finalized row is a leftover whose "ended" edit would otherwise
        # wait out the stale window while two LIVE posts fight the
        # bottom-anchor logic in a delete/repost ping-pong. Finalize content
        # is composed per row so each leftover links ITS OWN stored VODs.
        stale_rows = (await db.execute(text("""
            SELECT post_key, twitch_vod_url, youtube_vod_url, matchups
              FROM stream_channel_posts
             WHERE post_key <> :k AND NOT finalized
        """), {"k": stream_session})).mappings().all()
        for sr in stale_rows:
            await db.execute(text("""
                UPDATE stream_channel_posts
                   SET finalized = TRUE, content = :c,
                       revision = revision + 1, updated_at = NOW()
                 WHERE post_key = :sk AND NOT finalized
            """), {"sk": sr["post_key"],
                   "c": _stream_ended_content(sr["twitch_vod_url"], sr["youtube_vod_url"],
                                              sr["matchups"])})
        score = await _stream_series_score(db, candidate)
        content = _stream_post_content(candidate, score)
        row = (await db.execute(text("""
            SELECT post_key, content, finalized FROM stream_channel_posts
             WHERE post_key = :k
        """), {"k": stream_session})).mappings().first()
        if row is None:
            await db.execute(text("""
                INSERT INTO stream_channel_posts (post_key, channel_id, content,
                                                  twitch_vod_url, youtube_vod_url)
                VALUES (:k, :ch, :c, :tv, :yv)
                ON CONFLICT (post_key) DO NOTHING
            """), {"k": stream_session, "ch": RANKED_STREAMING_CHANNEL_ID, "c": content,
                   "tv": tvod, "yv": yvod})
        elif row["finalized"]:
            # REOPEN (review F2): a transport-only outage longer than the
            # stale window finalizes a genuinely live session; the fresh live
            # claim (session id from a heartbeating file, 120s freshness gate)
            # is stronger evidence than the timeout that fired during the
            # gap. A genuinely NEW stream still gets a fresh session id.
            await db.execute(text("""
                UPDATE stream_channel_posts
                   SET finalized = FALSE, content = :c, revision = revision + 1,
                       twitch_vod_url = COALESCE(:tv, twitch_vod_url),
                       youtube_vod_url = COALESCE(:yv, youtube_vod_url),
                       last_live_at = NOW(), updated_at = NOW()
                 WHERE post_key = :k AND finalized
            """), {"k": stream_session, "c": content, "tv": tvod, "yv": yvod})
        elif row["content"] != content:
            await db.execute(text("""
                UPDATE stream_channel_posts
                   SET content = :c, revision = revision + 1,
                       twitch_vod_url = COALESCE(:tv, twitch_vod_url),
                       youtube_vod_url = COALESCE(:yv, youtube_vod_url),
                       last_live_at = NOW(), updated_at = NOW()
                 WHERE post_key = :k AND NOT finalized
            """), {"k": stream_session, "c": content, "tv": tvod, "yv": yvod})
        else:
            await db.execute(text("""
                UPDATE stream_channel_posts
                   SET last_live_at = NOW(),
                       twitch_vod_url = COALESCE(:tv, twitch_vod_url),
                       youtube_vod_url = COALESCE(:yv, youtube_vod_url)
                 WHERE post_key = :k AND NOT finalized
            """), {"k": stream_session, "tv": tvod, "yv": yvod})
        # Session matchup accumulation (Sid, Aug 18): each DISTINCT watched
        # matchup lands once, in order, capped at 25 — the finalize edit
        # renders the list under the VOD links. No revision bump: the LIVE
        # body doesn't change. CAST is load-bearing (#275): `matchups ||
        # :line` types the bare param as TEXT[] and asyncpg then rejects the
        # scalar, aborting the whole upkeep transaction.
        mline = _stream_matchup_line(candidate)
        if mline:
            await db.execute(text("""
                UPDATE stream_channel_posts
                   SET matchups = matchups || CAST(:line AS TEXT)
                 WHERE post_key = :k AND NOT finalized
                   AND NOT (:line = ANY(matchups))
                   AND COALESCE(array_length(matchups, 1), 0) < 25
            """), {"k": stream_session, "line": mline})
        await db.commit()
    except Exception as ex:
        try:
            await db.rollback()
        except Exception:
            pass
        print(f"[STREAM-POST] upkeep failed (non-fatal): {ex}")


@app.get("/api/v1/broadcast/target", tags=["Spectate"])
async def broadcast_target(
    request: Request,
    steam_id: str = Query(..., max_length=32),
    current: str | None = Query(None, max_length=64),
    activation_age: float | None = Query(None, ge=0, le=86400),
    exclude: str | None = Query(None, max_length=4096),
    acq_ticket: str | None = Query(None, max_length=128),
    acq_phase: str | None = Query(None, max_length=32),
    acq_age: float | None = Query(None, ge=0, le=600),
    stream_live: int | None = Query(None, ge=0, le=1),
    stream_session: str | None = Query(None, max_length=64),
    stream_tvod: str | None = Query(None, max_length=120),
    stream_yvod: str | None = Query(None, max_length=120),
    db: AsyncSession = Depends(get_db),
):
    if not await _strict_steam_session_ok(request, steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    if not _is_broadcast_account(steam_id):
        raise HTTPException(status_code=403, detail="broadcast_only")

    rows = (await db.execute(text("""
        SELECT id, mode, source_ref, room_name, room_region, roster,
               fighter_target, room_capacity, spectator_cap, protocol_min,
               phase, started_at, last_attest_at, last_battle_at
          FROM spectate_games
         WHERE ended_at IS NULL
           AND last_attest_at > NOW() - make_interval(secs => :fresh)
         ORDER BY started_at DESC
         LIMIT 30
    """), {"fresh": SPECTATE_ATTEST_FRESH_SECONDS})).mappings().all()

    all_candidates = []
    for game in rows:
        candidate = await _broadcast_candidate(db, game, steam_id)
        if candidate is not None:
            all_candidates.append(candidate)

    exclusions = _broadcast_exclusions(exclude)
    current_candidate = next((c for c in all_candidates if c["game_id"] == current), None)
    current_payload = None
    if current:
        reason = "ok"
        still_eligible = current_candidate is not None
        if current_candidate is not None and current_candidate["incarnation"] in exclusions:
            still_eligible, reason = False, "excluded"
        elif current_candidate is None:
            try:
                current_uuid = UUID(current)
            except Exception:
                current_uuid = None
            live = None
            if current_uuid is not None:
                live = (await db.execute(text("""
                    SELECT id, mode, source_ref, room_name, room_region, roster,
                           fighter_target, room_capacity, spectator_cap, protocol_min,
                           phase, started_at, last_attest_at, last_battle_at, ended_at
                      FROM spectate_games WHERE id = :gid
                """), {"gid": current_uuid})).mappings().first()
            if (live is not None
                    and _broadcast_incarnation(live) in exclusions):
                reason = "excluded"
            elif live is None or live["ended_at"] is not None:
                reason = "game_ended"
            else:
                ready, _ = await _spectate_game_ready(db, live)
                reason = "unready" if not ready else "inadmissible"
        current_payload = {"game_id": current, "still_eligible": still_eligible,
                           "reason": reason}

    eligible = [c for c in all_candidates if c["incarnation"] not in exclusions]
    eligible.sort(key=lambda c: (c["tier"], -c["score"], c["incarnation"]))
    tier_one = [c for c in eligible if c["tier"] == 1]
    if tier_one:
        rotation_set = tier_one
    elif eligible:
        floor = eligible[0]["score"] * 0.85
        rotation_set = [c for c in eligible if c["score"] >= floor]
    else:
        rotation_set = []

    now_mono = time.monotonic()
    by_inc = {c["incarnation"]: c for c in eligible}
    selected = by_inc.get(_broadcast_rotation["incarnation"])
    current_ok = (current_candidate is not None
                  and current_candidate["incarnation"] not in exclusions)

    if current_ok:
        selected = current_candidate
        _broadcast_rotation["incarnation"] = selected["incarnation"]
        if activation_age is not None:
            if _broadcast_rotation["activated_at"] is None:
                _broadcast_rotation["activated_at"] = now_mono - activation_age
            _broadcast_rotation["last_progress_at"] = now_mono
        elif (acq_ticket
              and (acq_ticket != _broadcast_rotation["acq_ticket"]
                   or acq_phase != _broadcast_rotation["acq_phase"])):
            _broadcast_rotation["last_progress_at"] = now_mono
            _broadcast_rotation["acq_ticket"] = acq_ticket
            _broadcast_rotation["acq_phase"] = acq_phase
    elif selected is not None and acq_ticket:
        # Every poll referencing the selected acquisition renews its progress
        # lease. A phase can legitimately last longer than 30 seconds; the
        # independent 240-second age ceiling prevents a stuck client from
        # pinning the selector indefinitely.
        _broadcast_rotation["last_progress_at"] = now_mono
        _broadcast_rotation["acq_ticket"] = acq_ticket
        _broadcast_rotation["acq_phase"] = acq_phase

    acq_stalled = bool(selected) and (
        now_mono - float(_broadcast_rotation["last_progress_at"] or
                         _broadcast_rotation["selected_at"] or now_mono)
        > BROADCAST_ACQ_STALL_SECONDS)
    acq_over = acq_age is not None and acq_age > BROADCAST_ACQ_CEILING_SECONDS
    dwell_done = bool(current_ok and activation_age is not None
                      and activation_age >= BROADCAST_ROTATE_SECONDS)

    choose_new = selected is None or acq_stalled or acq_over
    # Bug 244: the dwell rotation must also fire when the pinned current
    # selection is NOT a member of the rotation set — a strictly better
    # class of game exists (a lone 2v2 outscoring the watched 1v1 past the
    # 0.85 floor, or a lone tier-1 tournament game) and `len > 1` alone can
    # never see it, so the seat stayed on the lesser game forever. The
    # dwell gate still applies: no switch inside BROADCAST_ROTATE_SECONDS.
    selected_in_rotation = bool(
        selected is not None
        and any(c["incarnation"] == selected["incarnation"]
                for c in rotation_set))
    if dwell_done and (len(rotation_set) > 1 or not selected_in_rotation):
        choose_new = True
    if current_payload is not None and not current_payload["still_eligible"]:
        choose_new = True

    if choose_new and rotation_set:
        choices = rotation_set
        if dwell_done and selected is not None:
            alternatives = [c for c in choices if c["incarnation"] != selected["incarnation"]]
            if alternatives:
                choices = alternatives
        selected = min(
            choices,
            key=lambda c: (_broadcast_rotation["last_shown"].get(c["incarnation"], 0.0),
                           c["incarnation"]),
        )
        _broadcast_rotation["incarnation"] = selected["incarnation"]
        _broadcast_rotation["selected_at"] = now_mono
        _broadcast_rotation["activated_at"] = None
        _broadcast_rotation["last_progress_at"] = now_mono
        _broadcast_rotation["acq_ticket"] = None
        _broadcast_rotation["acq_phase"] = None
        _broadcast_rotation["last_shown"][selected["incarnation"]] = now_mono
        # L1: bound the dict — drop entries for incarnations no longer live.
        live_incs = {c["incarnation"] for c in all_candidates}
        for stale_inc in [k for k in _broadcast_rotation["last_shown"] if k not in live_incs]:
            del _broadcast_rotation["last_shown"][stale_inc]
    elif not rotation_set:
        selected = None
        _broadcast_rotation["incarnation"] = None
        _broadcast_rotation["activated_at"] = None
        _broadcast_rotation["acq_ticket"] = None
        _broadcast_rotation["acq_phase"] = None

    next_switch = BROADCAST_ROTATE_SECONDS
    if current_ok and activation_age is not None:
        next_switch = max(0, int(BROADCAST_ROTATE_SECONDS - activation_age))

    # Living stream post upkeep (Aug 17). The post describes what the seat is
    # WATCHING (current), falling back to the director's selection while a
    # switch is in flight. No-op unless the poll carries stream_live. The
    # series score is derived server-side from the same candidate (review F1).
    await _stream_post_upkeep(db, stream_live, stream_session,
                              current_candidate if current_ok else selected,
                              stream_tvod, stream_yvod)

    return {
        "target": _broadcast_public(selected) if selected else None,
        "current": current_payload,
        "rotation": {"set_size": len(rotation_set), "next_switch_in": next_switch},
        "candidates": [_broadcast_public(c) for c in eligible[:5]],
    }


# ── W7 end authority (D1 f6/f7, Aug 19) ──────────────────────────────────
# The VM's post-session report engine needs a server-truth answer to "is
# this watched game OVER, and when": `ended_at != NULL` here is the ONLY
# terminal proof the report queue accepts. Absence from the games LIST
# proves nothing — rows age out of the list's attestation-freshness window
# while still open (#348) — so this is a direct by-id lookup, never a
# listing (#384a). Read-only, no writes, normal rate-limit gates apply
# (deliberately NOT on any bypass list, #285).
@app.get("/api/v1/broadcast/report-status", tags=["Spectate"])
async def broadcast_report_status(
    request: Request,
    steam_id: str = Query(..., max_length=32),
    # CSV of ≤8 UUIDs (36 chars each + commas); slack for whitespace only.
    game_ids: str = Query(..., max_length=512),
    db: AsyncSession = Depends(get_db),
):
    # AUTH FIRST, mirroring /broadcast/target verbatim (same seat, same two
    # helpers, same failure codes): fail-closed session check, then the
    # broadcast-account allowlist. #388's auth-before-work holds by
    # construction — a GET carries no body, and the id parsing below runs
    # only for the already-authenticated broadcast seat.
    if not await _strict_steam_session_ok(request, steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    if not _is_broadcast_account(steam_id):
        raise HTTPException(status_code=403, detail="broadcast_only")

    requested = []
    for item in game_ids.split(","):
        item = item.strip()
        if not item:
            continue
        try:
            gid = UUID(item)
        except (ValueError, AttributeError, TypeError):
            raise HTTPException(status_code=400, detail="invalid_game_id")
        if gid not in requested:  # dedupe, preserving request order
            requested.append(gid)
    if not requested:
        raise HTTPException(status_code=400, detail="no_game_ids")
    if len(requested) > 8:
        raise HTTPException(status_code=400, detail="too_many_game_ids")

    games = (await db.execute(text("""
        SELECT id, mode, started_at, ended_at, roster
          FROM spectate_games
         WHERE id = ANY(CAST(:gids AS uuid[]))
    """), {"gids": requested})).mappings().all()
    by_id = {g["id"]: g for g in games}

    # Display names for every roster member across all found games, in one
    # query. The roster steam-id CSV is returned exactly as stored: the
    # broadcast seat is already trusted with roster ids at grant time
    # (SpectateGameInfo.roster), so exposing them here to the SAME
    # authenticated seat adds no new exposure.
    all_sids = sorted({s for g in games
                       for s in _spectate_roster_list(g["roster"])})
    names_by_sid = {}
    if all_sids:
        rows = (await db.execute(text("""
            SELECT steam_id, display_name FROM players
             WHERE steam_id = ANY(CAST(:sids AS text[]))
        """), {"sids": all_sids})).mappings().all()
        names_by_sid = {r["steam_id"]: (r["display_name"] or "?") for r in rows}

    out = []
    for gid in requested:  # request order; ids with no row are omitted
        g = by_id.get(gid)
        if g is None:
            continue
        roster = _spectate_roster_list(g["roster"])
        out.append({
            "game_id": str(g["id"]),
            "mode": g["mode"],
            # TIMESTAMPTZ rows come back tz-aware, so isoformat() carries
            # the +00:00 offset — ISO 8601 UTC as the report engine expects.
            "started_at": g["started_at"].isoformat() if g["started_at"] else None,
            "ended_at": g["ended_at"].isoformat() if g["ended_at"] else None,
            "roster": g["roster"],
            # Ordered to match the roster CSV; unknown ids render "?" the
            # same way _broadcast_candidate does.
            "names": [names_by_sid.get(s, "?") for s in roster],
        })
    return out


@app.post("/api/v1/spectate/grant", tags=["Spectate"])
async def spectate_grant(req: SpectateGrantBody, request: Request,
                         db: AsyncSession = Depends(get_db)):
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    if req.client_protocol < SPECTATE_PROTOCOL:
        raise HTTPException(status_code=426, detail="spectator_upgrade_required")

    game = (await db.execute(text("""
        SELECT id, mode, source_ref, room_name, room_region, roster,
               fighter_target, room_capacity, spectator_cap, protocol_min, phase,
               last_attest_at, last_battle_at
          FROM spectate_games
         WHERE id = CAST(:gid AS UUID) AND ended_at IS NULL
    """), {"gid": req.game_id})).mappings().first()
    if game is None or game["last_attest_at"] is None:
        raise HTTPException(status_code=404, detail="game_not_live")
    # Aug 7 item 13: the grant enforces the same per-mode flag the games list
    # advertises — a crafted request must not watch a mode the UI hides.
    if game["mode"] not in _SPECTATE_WATCHABLE_MODES:
        raise HTTPException(status_code=409, detail="mode_not_ready")

    # Advisory locks: spectator + every roster member, canonical sorted order
    # (#197) — serializes against concurrent grants, opt-out toggles and the
    # one-active-lease rule.
    roster = _spectate_roster_list(game["roster"])
    if req.steam_id in roster:
        raise HTTPException(status_code=409, detail="already_in_game")
    for sid in sorted(set(roster + [req.steam_id])):
        await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"), {"sid": sid})

    # Authoritative re-reads under the locks (#208).
    game = (await db.execute(text("""
        SELECT id, mode, source_ref, room_name, room_region, roster, fighter_target,
               room_capacity, spectator_cap, protocol_min, phase,
               last_attest_at, last_battle_at
          FROM spectate_games
         WHERE id = CAST(:gid AS UUID) AND ended_at IS NULL
           AND last_attest_at > NOW() - make_interval(secs => :fresh)
    """), {"gid": req.game_id, "fresh": SPECTATE_ATTEST_FRESH_SECONDS})).mappings().first()
    if game is None:
        raise HTTPException(status_code=404, detail="game_not_live")
    ready, reason = await _spectate_game_ready(db, game)
    if not ready:
        raise HTTPException(status_code=409, detail=reason or "room_not_ready")

    # One active lease per account, REVOKE-AND-REPLACE (Codex r1 find 14):
    # a lost grant response leaves a live lease the client never learned of;
    # a 409 here would strand them until expiry. The advisory lock above
    # serializes concurrent grants for this account, so replacing is safe —
    # the old seat dies (its heartbeat now 410s) and the new one is the only
    # live lease. This runs BEFORE the seat-cap check (Codex r2 find 12: the
    # caller's own stale lease occupying the last seat otherwise makes their
    # retry 409 spectator_full).
    # Replacement ends the old authorization but is not proof the old Photon
    # actor departed. Persist its room-identity drain before revocation.
    await db.execute(text("""
        INSERT INTO spectate_drain_tombstones
            (room_name, region, ghost_steam_id, created_at)
        SELECT g.room_name, COALESCE(g.room_region, ''),
               l.spectator_steam_id, clock_timestamp()
          FROM spectate_leases l JOIN spectate_games g ON g.id = l.game_id
         WHERE l.spectator_steam_id = :sid AND l.revoked_at IS NULL
        ON CONFLICT (room_name, region, ghost_steam_id) DO NOTHING
    """), {"sid": req.steam_id})
    await db.execute(text("""
        UPDATE spectate_leases SET revoked_at = clock_timestamp()
         WHERE spectator_steam_id = :sid AND revoked_at IS NULL
    """), {"sid": req.steam_id})
    admission = await _spectate_admission(
        db, game, requester_steam_id=req.steam_id,
        broadcast=_is_broadcast_account(req.steam_id))
    if not admission["allowed"]:
        raise HTTPException(status_code=409, detail="spectator_full")

    token = secrets.token_urlsafe(24)
    lease_id = str(uuid.uuid4())
    await db.execute(text("""
        INSERT INTO spectate_leases
            (id, token_hash, game_id, spectator_steam_id,
             join_expires_at, heartbeat_expires_at, protocol)
        VALUES (CAST(:id AS UUID), :th, :gid, :sid,
                NOW() + make_interval(secs => :joinw),
                NOW() + make_interval(secs => :hbw), :proto)
    """), {"id": lease_id, "th": hashlib.sha256(token.encode()).hexdigest(),
           "gid": str(game["id"]), "sid": req.steam_id,
           "joinw": SPECTATE_JOIN_WINDOW_SECONDS,
           "hbw": SPECTATE_JOIN_WINDOW_SECONDS + SPECTATE_HEARTBEAT_TTL_SECONDS,
           "proto": SPECTATE_PROTOCOL})
    # A replacement lease is a new authorization generation for this actor.
    # Retain the physical tombstone, but advance its causal fence once here;
    # repeated dead heartbeats must not keep refreshing it forever.
    await db.execute(text("""
        UPDATE spectate_drain_tombstones
           SET created_at = clock_timestamp()
         WHERE room_name = :room AND region = :region AND ghost_steam_id = :sid
    """), {"room": game["room_name"], "region": game["room_region"] or "",
            "sid": req.steam_id})
    await db.commit()
    # The ONLY place the room credential leaves the server (§6.2).
    return {
        "lease_id": lease_id,
        "lease_token": token,
        "room_name": game["room_name"],
        "region": game["room_region"],
        "join_expires_in": SPECTATE_JOIN_WINDOW_SECONDS,
        "heartbeat_interval": 15,
        "protocol": SPECTATE_PROTOCOL,
    }


@app.post("/api/v1/spectate/heartbeat", tags=["Spectate"])
async def spectate_heartbeat(req: SpectateLeaseBody, request: Request,
                             db: AsyncSession = Depends(get_db)):
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    # Savepoint (#235 + Aug 10 r3 find 6): this SELECT reads the
    # migration-210 column. If the API ever runs ahead of the migration the
    # statement fails — which must be FAIL CLOSED (410, client leaves), not
    # an ignored 500 that leaves the seat locally admitted.
    lease = None
    try:
        async with db.begin_nested():
            lease = (await db.execute(text("""
                SELECT l.id, l.game_id, l.revoked_at, l.heartbeat_expires_at, l.protocol,
                        g.ended_at, g.roster, g.last_attest_at, g.last_battle_at, g.mode,
                        g.protocol_min, g.source_ref, g.room_name, g.room_region
                  FROM spectate_leases l
                  JOIN spectate_games g ON g.id = l.game_id
                 WHERE l.id = CAST(:lid AS UUID) AND l.spectator_steam_id = :sid
            """), {"lid": req.lease_id, "sid": req.steam_id})).mappings().first()
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=410, detail="lease_ended")
    if lease is None:
        raise HTTPException(status_code=404, detail="lease_unknown")
    now_dead = (lease["revoked_at"] is not None
                or lease["ended_at"] is not None
                # Codex r1 f8: pulling a mode from _SPECTATE_WATCHABLE_MODES
                # must also EVICT existing viewers, not just stop new grants —
                # without this a live lease kept renewing through the rollback
                # for the rest of the game.
                or lease["mode"] not in _SPECTATE_WATCHABLE_MODES
                # Aug 10 r2 blocker 1: a lease minted under an older protocol
                # must die when the game's floor advances past it — without
                # this, a protocol bump never evicts already-seated viewers
                # (grants created in a mixed-deploy window kept renewing).
                or (lease["protocol"] or 1) < max(lease["protocol_min"] or 1, SPECTATE_PROTOCOL)
                or lease["heartbeat_expires_at"] < datetime.now(timezone.utc)
                or lease["last_attest_at"] < datetime.now(timezone.utc) - timedelta(seconds=SPECTATE_ATTEST_FRESH_SECONDS * 2)
                # No live COMBAT recently = the sitting is over (Codex r2
                # find 13: attest freshness alone let a lease outlive the
                # match by the full double window).
                or lease["last_battle_at"] < datetime.now(timezone.utc) - timedelta(seconds=SPECTATE_ATTEST_FRESH_SECONDS * 2))
    if not now_dead:
        # Mid-match opt-out = immediate removal (design §6.7 recommendation):
        # any roster member's revoked consent kills the lease on the next beat.
        opt = (await db.execute(text("""
            SELECT COUNT(*) FROM players
             WHERE steam_id = ANY(:sids) AND allow_spectators IS NOT TRUE
        """), {"sids": _spectate_roster_list(lease["roster"])})).scalar() or 0
        if opt > 0:
            if not await _spectate_mandatory_class(db, lease):
                now_dead = True
    if now_dead:
        await db.execute(text("""
            UPDATE spectate_leases SET revoked_at = COALESCE(revoked_at, clock_timestamp())
             WHERE id = CAST(:lid AS UUID)
        """), {"lid": req.lease_id})
        # Revocation is part of the same transaction, so the shared helper now
        # sees this exact authorization-ending lease and persists its drain.
        await _spectate_record_drains(db, lease)
        await db.commit()
        raise HTTPException(status_code=410, detail="lease_ended")
    await db.execute(text("""
        UPDATE spectate_leases
           SET heartbeat_expires_at = clock_timestamp() + make_interval(secs => :ttl)
         WHERE id = CAST(:lid AS UUID)
    """), {"lid": req.lease_id, "ttl": SPECTATE_HEARTBEAT_TTL_SECONDS})
    await db.commit()
    return {"status": "ok"}


@app.post("/api/v1/spectate/leave", tags=["Spectate"])
async def spectate_leave(req: SpectateLeaseBody, request: Request,
                         db: AsyncSession = Depends(get_db)):
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    # Leave is intent, not departure proof. Enter durable drain first; only a
    # later complete master inventory may clear it.
    await db.execute(text("""
        INSERT INTO spectate_drain_tombstones
            (room_name, region, ghost_steam_id, created_at)
        SELECT g.room_name, COALESCE(g.room_region, ''),
               l.spectator_steam_id, clock_timestamp()
          FROM spectate_leases l JOIN spectate_games g ON g.id = l.game_id
         WHERE l.id = CAST(:lid AS UUID) AND l.spectator_steam_id = :sid
        ON CONFLICT (room_name, region, ghost_steam_id) DO NOTHING
    """), {"lid": req.lease_id, "sid": req.steam_id})
    await db.execute(text("""
        UPDATE spectate_leases SET revoked_at = COALESCE(revoked_at, clock_timestamp())
         WHERE id = CAST(:lid AS UUID) AND spectator_steam_id = :sid
    """), {"lid": req.lease_id, "sid": req.steam_id})
    await db.commit()
    return {"status": "ok"}


@app.post("/api/v1/spectate/validate", tags=["Spectate"])
async def spectate_validate(req: SpectateValidateBody, request: Request,
                            db: AsyncSession = Depends(get_db)):
    """Master-fighter validation of claimed spectator actors (§6.6). The
    caller must itself be a session-verified member of the room's roster —
    a stranger cannot use this endpoint as a lease oracle."""
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    # Database clock fence: PostgreSQL NOW() is transaction-start time and
    # cannot prove receipt ordering. clock_timestamp() is sampled before any
    # drains created by this inventory and shares the tombstone clock domain.
    received_at = (await db.execute(text("SELECT clock_timestamp()"))).scalar_one()
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:k))"),
                     {"k": f"spectate:{req.room_name}"})
    game = (await db.execute(text("""
        SELECT id, roster, mode, source_ref, room_name, room_region, protocol_min
          FROM spectate_games
         WHERE room_name = :room AND ended_at IS NULL
    """), {"room": req.room_name})).mappings().first()
    if game is None:
        raise HTTPException(status_code=404, detail="game_not_live")
    if req.steam_id not in _spectate_roster_list(game["roster"]):
        raise HTTPException(status_code=403, detail="not_a_participant")
    await _assert_no_service_subject(
        db, affected_steam_ids=_spectate_roster_list(game["roster"]))
    observed_sids = {entry.steam_id for entry in req.spectators[:8] if entry.steam_id}

    # Materialize every authorization-ended current-row actor as a durable
    # drain. This includes natural expiry; elapsed time never frees a seat.
    await _spectate_record_drains(db, game)

    # This submission is the room master's complete observed spectator set
    # (the cap of eight exceeds physical spectator capacity). Clearance is
    # fenced to this LIVE room+region and to tombstones that existed before
    # this request reached the server. A delayed pre-drain snapshot therefore
    # cannot clear a newer tombstone, regardless of client clocks.
    await db.execute(text("""
        DELETE FROM spectate_drain_tombstones
         WHERE room_name = :room AND region = :region
           AND created_at < :received
           AND NOT (ghost_steam_id = ANY(CAST(:observed AS text[])))
    """), {"room": game["room_name"], "region": game["room_region"] or "",
            "received": received_at, "observed": sorted(observed_sids)})
    # Integration fix (cold review H1): only sweep leases whose AUTHORIZATION
    # already ended. Without the fence this deleted LIVE leases still inside
    # their join window (a granted-but-not-yet-joined spectator, including the
    # broadcast seat's long acquisition arc) whenever a validate sweep landed
    # first -> entry-validate found no lease -> master kicked the newcomer.
    # Live-but-departed seats still die via expiry -> drain -> next sweep.
    await db.execute(text("""
        DELETE FROM spectate_leases
         WHERE game_id = :gid
           AND NOT (spectator_steam_id = ANY(CAST(:observed AS text[])))
           AND (revoked_at IS NOT NULL OR heartbeat_expires_at <= NOW())
    """), {"gid": str(game["id"]), "observed": sorted(observed_sids)})
    # Codex r1 f8: a rolled-back mode fails validation too, so the fighters'
    # admission set drops existing watchers instead of honoring their leases
    # for the rest of the game.
    _mode_ok = game["mode"] in _SPECTATE_WATCHABLE_MODES
    results = []
    for entry in req.spectators[:8]:
        ok = False
        display = ""
        if entry.steam_id and _mode_ok:
            # ACTOR BINDING (Codex r1 find 3): the first validation binds the
            # lease to this ActorNumber; any other actor claiming the same
            # identity finds the lease bound elsewhere and fails. One lease =
            # one Photon seat.
            # protocol >= the game's floor (Aug 10 r2 blocker 1): validation
            # is what keeps a seat open, so a stale-protocol lease must fail
            # here too, not only at its own heartbeat. Savepoint (#235 + r3
            # find 6): a missing migration-210 column must yield ok=False for
            # this actor (fail closed), not poison the whole transaction.
            lease = None
            try:
                async with db.begin_nested():
                    lease = (await db.execute(text("""
                        UPDATE spectate_leases
                           SET bound_actor = :actor
                         WHERE game_id = :gid AND spectator_steam_id = :sid
                           AND revoked_at IS NULL AND heartbeat_expires_at > NOW()
                           AND COALESCE(protocol, 1) >= :pmin
                           AND (bound_actor IS NULL OR bound_actor = :actor)
                        RETURNING id
                    """), {"gid": str(game["id"]), "sid": entry.steam_id,
                           "actor": entry.actor_number,
                           "pmin": max(int(game.get("protocol_min") or 1), SPECTATE_PROTOCOL)})).first()
            except Exception:
                lease = None
            if lease is not None:
                ok = True
                display = (await db.execute(text("""
                    SELECT display_name FROM players WHERE steam_id = :sid
                """), {"sid": entry.steam_id})).scalar() or ""
        results.append({"actor_number": entry.actor_number, "ok": ok,
                        "display_name": display})
    await db.commit()
    return {"results": results}


@app.post("/api/v1/settings/allow-spectators", tags=["Spectate"])
async def set_allow_spectators(req: AllowSpectatorsBody, request: Request,
                               db: AsyncSession = Depends(get_db)):
    if not await _strict_steam_session_ok(request, req.steam_id, db):
        raise HTTPException(status_code=401, detail="session_required")
    # Serialize against concurrent grant issuance (§6.7): the grant path
    # advisory-locks every roster member, so locking ourselves here means a
    # racing grant either sees the new value or completes first — and in the
    # completes-first case the next heartbeat revokes within 15s.
    await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"), {"sid": req.steam_id})
    await db.execute(text("""
        UPDATE players SET allow_spectators = :v WHERE steam_id = :sid
    """), {"v": bool(req.allow), "sid": req.steam_id})
    await db.commit()
    return {"status": "ok", "allow_spectators": bool(req.allow)}
